window.CHINESE_DOC_WORKS=[{"id":"docx_1","theme":1,"title":"子路、曾皙、冉有、公西华侍坐","author":"《论语》〔先秦〕","genre":"古文","idea":"文章以“言志 ”为线索，记述了孔子和他的四个弟子的一次谈话，反映儒家的政治主张和治国理念；通过富 有个性的语言和生动简洁的动作、神态描写，表现了各个人物的精神风貌和思想态度。","central":"子路、曾皙、冉有、公西华侍坐。","options":["文章以“言志 ”为线索，记述了孔子和他的四个弟子的一次谈话，反映儒家的政治主张和治国理念；通过富 有个性的语言和生动简洁的动作、神态描写，表现了各个人物的精神风貌和思想态度。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"子路、曾皙、冉有、公西华侍坐。","meaning":"围绕“子路、曾皙、冉有、公”展","central":"子路、曾皙、冉有、公西华侍坐。","words":[],"markedWords":["侍坐"]},{"text":"子曰：“以吾一日长乎尔，毋吾以也。居则曰：‘不吾知也。’如","meaning":"围绕“子曰以吾一日长乎尔毋”展","central":"子曰：“以吾一日长乎尔，毋吾以也。","words":[],"markedWords":["以","长","居","不吾知","如"]},{"text":"ǐ子路：“不挨打”即“强兵”。","meaning":"围绕“ǐ子路不挨打即强兵”展开","central":"ǐ子路：“不挨打”即“强兵”。","words":[],"markedWords":["jǐn"]},{"text":"（兼词，于是，在这场合里）。”公西华：“知礼节”即“文明”","meaning":"围绕“兼词于是在这场合里”展开","central":"（兼词，于是，在这场合里）。","words":[],"markedWords":[]},{"text":"子曰：“何伤乎？亦各言其志也。”","meaning":"围绕“子曰何伤乎”展开","central":"子曰：“何伤乎？","words":[],"markedWords":["何伤"]},{"text":"咏而归。”曾皙：“幸福”是治国的终极目标","meaning":"第二部分：弟子述志。子路的直率","central":"咏而归。","words":[],"markedWords":["咏"]},{"text":"夫子喟然叹曰：“吾与点也！”→","meaning":"围绕“夫子喟然叹曰吾与点也”展","central":"夫子喟然叹曰：“吾与点也！","words":[],"markedWords":["喟然","与"]},{"text":"曰：“为国以礼，其言不让，是故哂之。","meaning":"围绕“曰为国以礼其言不让是”展","central":"曰：“为国以礼，其言不让，是故哂之。","words":[],"markedWords":["为国以礼","其言不让"]},{"text":"(唯：语气助词，用于句首，无实意。也与，语气助词，表示疑问。）","meaning":"围绕“(唯语气助词用于句首”展","central":"(唯：语气助词，用于句首，无实意。","words":[],"markedWords":[]},{"text":"“安见方六七十，如五六十而非邦也者？”","meaning":"围绕“安见方六七十如五六十”展","central":"“安见方六七十，如五六十而非邦也者？","words":[],"markedWords":["安见"]},{"text":"“宗庙会同，非诸侯而何？赤也为之小，孰能为之大？”→","meaning":"第三部分：孔子评志。从孔子对学","central":"“宗庙会同，非诸侯而何？","words":[],"markedWords":[]}]},{"id":"docx_2","theme":0,"title":"齐桓晋文之事","author":"孟子及弟子〔先秦〕","genre":"古文","idea":"孟子通过亲切生动的举例，明确犀利的语言，最终说动了齐宣王，并从正面提出了自己“保民而王 ”的政治 理想，比较系统地阐述了他的“仁政 ”主张。","central":"齐宣王问曰：“齐桓、晋文之事可得闻乎？","options":["孟子通过亲切生动的举例，明确犀利的语言，最终说动了齐宣王，并从正面提出了自己“保民而王 ”的政治 理想，比较系统地阐述了他的“仁政 ”主张。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"齐宣王问曰：“齐桓、晋文之事可得闻乎？”","meaning":"围绕“齐宣王问曰齐桓、晋文”展","central":"齐宣王问曰：“齐桓、晋文之事可得闻乎？","words":[],"markedWords":[]},{"text":"曰：“若寡人者，可以保民乎哉？”","meaning":"围绕“曰若寡人者可以保民乎”展","central":"曰：“若寡人者，可以保民乎哉？","words":[],"markedWords":[]},{"text":"曰：“臣闻之胡龁曰：王坐于堂上，有牵牛而过堂下者，王见之，曰：","meaning":"围绕“曰臣闻之胡龁曰王坐于”展","central":"曰：“臣闻之胡龁曰：王坐于堂上，有牵牛而过堂下者，王见之，曰：","words":[],"markedWords":[]},{"text":"而就死地。’对曰：‘然则废衅钟与？’曰：‘何可废也，以羊易之。’不","meaning":"围绕“而就死地”展开","central":"而就死地。","words":[],"markedWords":["就","与","以羊易之"]},{"text":"曰：“是心足以王矣。百姓皆以王爱也，臣固知王之不忍也。”","meaning":"围绕“曰是心足以王矣”展开","central":"曰：“是心足以王矣。","words":[],"markedWords":["王","爱"]},{"text":"王曰：“然，诚有百姓者。齐国虽褊小，吾何爱一牛？即不忍其觳觫，","meaning":"围绕“王曰然诚有百姓者”展开","central":"王曰：“然，诚有百姓者。","words":[],"markedWords":["诚","有百姓者","褊小","爱"]},{"text":"若无罪而就死地，故以羊易之也。”","meaning":"围绕“若无罪而就死地故以羊”展","central":"若无罪而就死地，故以羊易之也。","words":[],"markedWords":[]},{"text":"曰：“王无异于百姓之以王为爱也。以小易大，彼恶知之？王若隐其无","meaning":"围绕“曰王无异于百姓之以王”展","central":"曰：“王无异于百姓之以王为爱也。","words":[],"markedWords":["异","恶","隐"]},{"text":"王说，曰：“《诗》云：‘他人有心，予忖度之。’夫子之谓也。夫我","meaning":"围绕“王说曰《诗》云‘他人”展","central":"王说，曰：“《诗》云：‘他人有心，予忖度之。","words":[],"markedWords":["说","他人有心予忖度之","夫子之","谓也"]},{"text":"乃行之，反而求之，不得吾心；夫子言之，于我心有戚戚焉。此心之所以合","meaning":"围绕“乃行之反而求之不得吾”展","central":"乃行之，反而求之，不得吾心；","words":[],"markedWords":["戚戚"]}]},{"id":"docx_3","theme":1,"title":"庖丁解牛","author":"庄子〔先秦〕","genre":"古文","idea":"通过记叙梁惠王与庖丁之间的回答，揭示了一切事物都有其客观规律的道理，表明我们应该在实践中不断积 累经验，善于总结，把握规律之后，仍要谨慎戒惧地面对具体问题，才能把事情做好。","central":"庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然","options":["通过记叙梁惠王与庖丁之间的回答，揭示了一切事物都有其客观规律的道理，表明我们应该在实践中不断积 累经验，善于总结，把握规律之后，仍要谨慎戒惧地面对具体问题，才能把事情做好。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然","meaning":"庖丁为梁惠王解牛的熟练动作和美","central":"庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然","words":[],"markedWords":["所触","履","踦"]},{"text":"文惠君曰：“嘻，善哉！技盖至此乎？”","meaning":"围绕“文惠君曰嘻善哉”展开","central":"文惠君曰：“嘻，善哉！","words":[],"markedWords":["嘻","盖"]},{"text":"庖丁释刀对曰：“臣之所好者道也，进乎技矣。始臣之解牛之时，所见","meaning":"庖丁对梁惠王提出的问题进行了解","central":"庖丁释刀对曰：“臣之所好者道也，进乎技矣。","words":[],"markedWords":["道","进","乎技矣"]},{"text":"无非牛者。三年之后，未尝见全牛也。方今之时，臣以神遇而不以目视，官","meaning":"围绕“无非牛者”展开","central":"无非牛者。","words":[],"markedWords":["无非","牛者","未尝见全牛也","臣以神","遇","而不以目视"]},{"text":"知止而神欲行。依乎天理，批大郤，导大窾，","meaning":"围绕“知止而神欲行”展开","central":"知止而神欲行。","words":[],"markedWords":["止而","神欲","行","天理","郤","导"]},{"text":"所解数千牛矣，而刀刃若新发于硎。彼节者有间，而刀刃者无厚；以无厚入","meaning":"围绕“所解数千牛矣而刀刃若”展","central":"所解数千牛矣，而刀刃若新发于硎。","words":[],"markedWords":["间","无","厚"]},{"text":"如写庖丁解牛时手、肩足、膝的动作，只用触、倚、履、踦四字，便反映出各自的特色。","meaning":"围绕“如写庖丁解牛时手、肩”展","central":"如写庖丁解牛时手、肩足、膝的动作，只用触、倚、履、踦四字，便反映出各自的特色。","words":[],"markedWords":["触、倚、履、踦"]},{"text":"用“嘻，善哉！技盖至此乎？”八个字，将梁惠王看到庖丁高超的解牛技术而产生的惊异、赞叹与疑惑不解的表现真实地反映出来。","meaning":"围绕“用嘻善哉”展开","central":"用“嘻，善哉！","words":[],"markedWords":["嘻善哉技盖至此乎"]}]},{"id":"docx_4","theme":2,"title":"烛之武退秦师","author":"左丘明〔先秦〕","genre":"古文","idea":"记述了秦、晋围郑，郑国烛之武说退秦师，从而解除郑国危机的过程，刻画了烛之武以国为重、能言善辩、 不卑不亢的形象。","central":"用子，今急而求子，是寡人之过也。","options":["记述了秦、晋围郑，郑国烛之武说退秦师，从而解除郑国危机的过程，刻画了烛之武以国为重、能言善辩、 不卑不亢的形象。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"用子，今急而求子，是寡人之过也。然郑亡，子亦有不利焉！”许之。","meaning":"围绕“用子今急而求子是寡人”展","central":"用子，今急而求子，是寡人之过也。","words":[],"markedWords":["许"]},{"text":"夜缒而出，见秦伯，曰：“秦、晋围郑，郑既知亡矣。若亡郑而有益于","meaning":"围绕“夜缒而出见秦伯曰秦、”展","central":"夜缒而出，见秦伯，曰：“秦、晋围郑，郑既知亡矣。","words":[],"markedWords":["缒","既","亡"]},{"text":"君，敢以烦执事。越国以鄙远，君知其难也，焉用亡郑以陪邻？邻之厚，君","meaning":"围绕“君敢以烦执事”展开","central":"君，敢以烦执事。","words":[],"markedWords":["敢以烦执事","越国以","远","焉用亡郑以","邻","邻之","君"]},{"text":"之薄也。若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。且君尝","meaning":"围绕“之薄也”展开","central":"之薄也。","words":[],"markedWords":["之","也","若舍郑","以为东道主","行李","共","其乏困","尝"]},{"text":"，又欲肆其西封，若不阙秦，将焉取之？阙秦以利晋，唯君图之。”","meaning":"围绕“又欲肆其西封若不阙秦”展","central":"，又欲肆其西封，若不阙秦，将焉取之？","words":[],"markedWords":["其","西","封","秦","将","取之","利","君图之"]},{"text":"子犯请击之。公曰：“不可。微夫人之力不及此。因人之力而敝之，不","meaning":"围绕“子犯请击之”展开","central":"子犯请击之。","words":[],"markedWords":["夫人","之力不及此","人之力而","之不"]},{"text":"仁；失其所与，不知；以乱易整，不武。吾其还也。”亦去之。","meaning":"围绕“仁”展开","central":"仁；","words":[],"markedWords":["仁","失其所","不","以乱易","吾","还也","去"]},{"text":"左丘明：春秋末期鲁国人，史学家，知识渊博，品德高尚，孔子言与其同耻，太史公司马迁称其为“鲁之君子”。","meaning":"围绕“左丘明春秋末期鲁国人”展","central":"左丘明：春秋末期鲁国人，史学家，知识渊博，品德高尚，孔子言与其同耻，太史公司马迁称其为“鲁之君子”。","words":[],"markedWords":["左丘明"]},{"text":"波澜起伏。郑国危在旦夕，佚之狐推荐烛之武，让郑国公看到希望。烛之武起初因长期得不到重用、老了更没用为理由推辞。郑文公自责，增加文章戏剧性。秦国退兵后，子犯请求攻打秦军，秦、晋关系紧张。晋文公讲了“仁”“知”“武”的道理，才避免战争。文章有驰有张，曲折有致，极具艺术感染力。","meaning":"围绕“波澜起伏”展开","central":"波澜起伏。","words":[],"markedWords":[]}]},{"id":"docx_5","theme":3,"title":"鸿门宴","author":"司马迁〔两汉〕","genre":"古文","idea":"写秦朝灭亡后，项羽、刘邦的首次矛盾斗争，这也是长达多年的楚汉战争的开端。本文通过对鸿门宴全过程 的描写，生动揭示了项羽自矜功伐的性格，表现了刘邦善于利用他人性格弱点和善于拉拢人，在某种程度上预示了 两人斗争的结局。","central":"之。","options":["写秦朝灭亡后，项羽、刘邦的首次矛盾斗争，这也是长达多年的楚汉战争的开端。本文通过对鸿门宴全过程 的描写，生动揭示了项羽自矜功伐的性格，表现了刘邦善于利用他人性格弱点和善于拉拢人，在某种程度上预示了 两人斗争的结局。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"之。”项羽大怒曰：“旦日飨士卒，为击破沛公军！”当是时，项羽兵四十","meaning":"围绕“之”展开","central":"之。","words":[],"markedWords":["飨"]},{"text":"万，在新丰鸿门；沛公兵十万，在霸上。范增说项羽曰：“沛公居山东时，","meaning":"围绕“万在新丰鸿门”展开","central":"万，在新丰鸿门；","words":[],"markedWords":["说","山东"]},{"text":"令人望其气，皆为龙虎，成五采，此天子气也。急击勿失！”","meaning":"→","central":"令人望其气，皆为龙虎，成五采，此天子气也。","words":[],"markedWords":["失"]},{"text":"也。”张良曰：“臣为韩王送沛公，沛公今事有急，亡去不义，不可不语。”","meaning":"围绕“也”展开","central":"也。","words":[],"markedWords":["语"]},{"text":"良乃入，具告沛公。沛公大惊，曰：“为之奈何？”张良曰：“谁为大王为","meaning":"围绕“良乃入具告沛公”展开","central":"良乃入，具告沛公。","words":[],"markedWords":[]},{"text":"此计者？”曰：“鲰生说我曰：‘距关，毋内诸侯，秦地可尽王也。’故听","meaning":"围绕“此计者”展开","central":"此计者？","words":[],"markedWords":["鲰","距","内"]},{"text":"且为之奈何？”张良曰：“请往谓项伯，言沛公不敢背项王也。”沛公曰：","meaning":"围绕“且为之奈何”展开","central":"且为之奈何？","words":[],"markedWords":[]},{"text":"“君安与项伯有故？”张良曰：“秦时与臣游，项伯杀人，臣活之。今事有","meaning":"围绕“君安与项伯有故”展开","central":"“君安与项伯有故？","words":[],"markedWords":["有","故","活","之"]},{"text":"“君为我呼入，吾得兄事之。”张良出，要项伯。项伯即入见沛公。沛公奉","meaning":"围绕“君为我呼入吾得兄事之”展","central":"“君为我呼入，吾得兄事之。","words":[],"markedWords":["兄事","之","要"]},{"text":"卮酒为寿，约为婚姻，曰：“吾入关，秋毫不敢有所近，籍吏民，封府库，","meaning":"围绕“卮酒为寿约为婚姻曰吾”展","central":"卮酒为寿，约为婚姻，曰：“吾入关，秋毫不敢有所近，籍吏民，封府库","words":[],"markedWords":["婚姻","秋毫不敢有所","近","籍","吏民"]},{"text":"而待将军。所以遣将守关者，备他盗之出入与非常也。日夜望将军至，岂敢","meaning":"围绕“而待将军”展开","central":"而待将军。","words":[],"markedWords":["非常"]},{"text":"反乎！愿伯具言臣之不敢倍德也。”项伯许诺，谓沛公曰：“旦日不可不蚤","meaning":"围绕“反乎”展开","central":"反乎！","words":[],"markedWords":["倍","德","蚤"]}]},{"id":"docx_6","theme":0,"title":"谏逐客书","author":"李斯〔先秦〕","genre":"古文","idea":"文章首先叙述秦国自秦穆公以来皆以客卿致强的史诗，说明秦若无客卿的辅助则未必强大的道理；然后将色、 乐、珠玉等虽非秦国所产却被秦王喜爱与客卿因不是秦国人而被驱逐的事实作比，说明秦王不应该重物轻人。文章 立意高深，始终围绕“大一统 ”的目标，从秦王统一天下的高度立论，正反论证，利害并举，说明客卿强国的重要 性。","central":"强，百姓乐用，诸侯亲服，获楚、魏之师，举地千里，至今治强。","options":["文章首先叙述秦国自秦穆公以来皆以客卿致强的史诗，说明秦若无客卿的辅助则未必强大的道理；然后将色、 乐、珠玉等虽非秦国所产却被秦王喜爱与客卿因不是秦国人而被驱逐的事实作比，说明秦王不应该重物轻人。文章 立意高深，始终围绕“大一统 ”的目标，从秦王统一天下的高度立论，正反论证，利害并举，说明客卿强国的重要 性。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"强，百姓乐用，诸侯亲服，获楚、魏之师，举地千里，至今治强。惠王用张","meaning":"围绕“强百姓乐用诸侯亲服获”展","central":"强，百姓乐用，诸侯亲服，获楚、魏之师，举地千里，至今治强。","words":[],"markedWords":["乐用","举","治强"]},{"text":"仪之计，拔三川之地，西并巴、蜀，北收上郡，南取汉中，包九夷，制鄢、","meaning":"围绕“仪之计拔三川之地西并”展","central":"仪之计，拔三川之地，西并巴、蜀，北收上郡，南取汉中，包九夷，制鄢","words":[],"markedWords":["并"]},{"text":"此四君者，皆以客之功。由此观之，客何负于秦哉！向使四君却客而不内，","meaning":"围绕“此四君者皆以客之功”展开","central":"此四君者，皆以客之功。","words":[],"markedWords":["向使","内"]},{"text":"疏士而不用，是使国无富利之实而秦无强大之名也。","meaning":"围绕“疏士而不用是使国无富”展","central":"疏士而不用，是使国无富利之实而秦无强大之名也。","words":[],"markedWords":[]},{"text":"今陛下致昆山之玉，有随、和之宝，垂明月之珠，服太阿之剑，乘纤离","meaning":"围绕“今陛下致昆山之玉有随”展","central":"今陛下致昆山之玉，有随、和之宝，垂明月之珠，服太阿之剑，乘纤离","words":[],"markedWords":[]},{"text":"之马，建翠凤之旗，树灵鼍之鼓。此数宝者，秦不生一焉，而陛下说之，何","meaning":"围绕“之马建翠凤之旗树灵鼍”展","central":"之马，建翠凤之旗，树灵鼍之鼓。","words":[],"markedWords":["建"]},{"text":"也？必秦国之所生然后可，则是夜光之璧不饰朝廷，犀象之器不为玩好，郑、","meaning":"围绕“也”展开","central":"也？","words":[],"markedWords":[]},{"text":"卫之女不充后宫，而骏良駃騠不实外厩，江南金锡不为用，西蜀丹青不为采。","meaning":"围绕“卫之女不充后宫而骏良”展","central":"卫之女不充后宫，而骏良駃騠不实外厩，江南金锡不为用，西蜀丹青不为采。","words":[],"markedWords":[]},{"text":"所以饰后宫，充下陈，娱心意，说耳目者，必出于秦然后可，则是宛珠之簪、","meaning":"围绕“所以饰后宫充下陈娱心”展","central":"所以饰后宫，充下陈，娱心意，说耳目者，必出于秦然后可，则是宛珠之","words":[],"markedWords":[]},{"text":"傅玑之珥、阿缟之衣、锦绣之饰不进于前，","meaning":"围绕“傅玑之珥、阿缟之衣、”展","central":"傅玑之珥、阿缟之衣、锦绣之饰不进于前，","words":[],"markedWords":[]},{"text":"侧也。夫击瓮叩缶，弹筝搏髀，而歌呼呜呜快耳者，真秦之声也；《郑》","meaning":"围绕“侧也”展开","central":"侧也。","words":[],"markedWords":[]},{"text":"《卫》《桑间》《昭》《虞》《武》《象》者，异国之乐也。今弃击瓮叩缶","meaning":"围绕“《卫》《桑间》《昭》”展","central":"《卫》《桑间》《昭》《虞》《武》《象》者，异国之乐也。","words":[],"markedWords":[]}]},{"id":"docx_7","theme":2,"title":"与妻书","author":"林觉民〔清代〕","genre":"古文","idea":"清朝末年革命烈士林觉民写给妻子陈意映的一封绝笔信。在这封绝笔信中，作者表达了自己对妻子之至爱和 对天下之大爱，将自己的革命理想与儿女情长抒发得淋漓尽致。他把家庭幸福、夫妻恩爱和国家前途、人民命运联 系在一起，把对妻子、儿女的爱和对国家、人民的爱连为一体，阐述了一个深刻的道理：没有国家和人民的幸福， 就不会有个人的真正幸福。","central":"意映卿卿如晤，吾今以此书与汝永别矣！","options":["清朝末年革命烈士林觉民写给妻子陈意映的一封绝笔信。在这封绝笔信中，作者表达了自己对妻子之至爱和 对天下之大爱，将自己的革命理想与儿女情长抒发得淋漓尽致。他把家庭幸福、夫妻恩爱和国家前途、人民命运联 系在一起，把对妻子、儿女的爱和对国家、人民的爱连为一体，阐述了一个深刻的道理：没有国家和人民的幸福， 就不会有个人的真正幸福。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"意映卿卿如晤，吾今以此书与汝永别矣！吾作此书时，尚是世中一人；","meaning":"围绕“意映卿卿如晤吾今以此”展","central":"意映卿卿如晤，吾今以此书与汝永别矣！","words":[],"markedWords":[]},{"text":"汝看此书时，吾已成为阴间一鬼。吾作此书，泪珠和笔墨齐下，不能竟书而","meaning":"围绕“汝看此书时吾已成为阴”展","central":"汝看此书时，吾已成为阴间一鬼。","words":[],"markedWords":["竟"]},{"text":"欲搁笔，又恐汝不察吾衷，谓吾忍舍汝而死，谓吾不知汝之不欲吾死也，故","meaning":"围绕“欲搁笔又恐汝不察吾衷”展","central":"欲搁笔，又恐汝不察吾衷，谓吾忍舍汝而死，谓吾不知汝之不欲吾死也，","words":[],"markedWords":["衷"]},{"text":"汝也。汝体吾此心，于啼泣之余，亦以天下人为念，当亦乐牺牲吾身与汝身","meaning":"围绕“汝也”展开","central":"汝也。","words":[],"markedWords":[]},{"text":"之福利，为天下人谋永福也。汝其勿悲！","meaning":"围绕“之福利为天下人谋永福”展","central":"之福利，为天下人谋永福也。","words":[],"markedWords":[]},{"text":"汝忆否？四五年前某夕，吾尝语曰：","meaning":"围绕“汝忆否”展开","central":"汝忆否？","words":[],"markedWords":[]},{"text":"死。”汝初闻言而怒，后经吾婉解，虽不谓吾言为是，而亦无词相答。吾之","meaning":"围绕“死”展开","central":"死。","words":[],"markedWords":[]},{"text":"意盖谓以汝之弱，必不能禁失吾之悲，吾先死，留苦与汝，吾心不忍，故宁","meaning":"围绕“意盖谓以汝之弱必不能”展","central":"意盖谓以汝之弱，必不能禁失吾之悲，吾先死，留苦与汝，吾心不忍，故","words":[],"markedWords":[]},{"text":"请汝先死，吾担悲也。嗟夫！谁知吾卒先汝而死乎？","meaning":"围绕“请汝先死吾担悲也”展开","central":"请汝先死，吾担悲也。","words":[],"markedWords":[]},{"text":"吾真真不能忘汝也！回忆后街之屋，入门穿廊，过前后厅，又三四折，","meaning":"围绕“吾真真不能忘汝也”展开","central":"吾真真不能忘汝也！","words":[],"markedWords":[]},{"text":"有小厅，厅旁一室，为吾与汝双栖之所。初婚三四个月，适冬之望日前后，","meaning":"围绕“有小厅厅旁一室为吾与”展","central":"有小厅，厅旁一室，为吾与汝双栖之所。","words":[],"markedWords":[]},{"text":"窗外疏梅筛月影，依稀掩映；吾与并肩携手，低低切切，何事不语？何情不","meaning":"围绕“窗外疏梅筛月影依稀掩”展","central":"窗外疏梅筛月影，依稀掩映；","words":[],"markedWords":[]}]},{"id":"docx_8","theme":5,"title":"促织","author":"蒲松龄〔清代〕","genre":"古文","idea":"以促织的得失为主要线索，通过讲述成名一家的遭遇，塑造了这一在官府逼迫之下痛苦挣扎的社会底层的读 书人的形象，表现了他由悲到喜、喜极而悲、悲极复喜的情绪变化，表达了作者对饱受虐吏猾胥迫害的平民百姓的 深切同情，揭露了各级官员为讨好皇帝而搜刮贡物，给人民带来的深重灾难，也批判了官贪吏虐的黑暗现实。","central":"官，以一头进，试使斗而才，因责常供。","options":["以促织的得失为主要线索，通过讲述成名一家的遭遇，塑造了这一在官府逼迫之下痛苦挣扎的社会底层的读 书人的形象，表现了他由悲到喜、喜极而悲、悲极复喜的情绪变化，表达了作者对饱受虐吏猾胥迫害的平民百姓的 深切同情，揭露了各级官员为讨好皇帝而搜刮贡物，给人民带来的深重灾难，也批判了官贪吏虐的黑暗现实。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"官，以一头进，试使斗而才，因责常供。令以责之里正。市中游侠儿得佳者","meaning":"围绕“官以一头进试使斗而才”展","central":"官，以一头进，试使斗而才，因责常供。","words":[],"markedWords":["进","才","责","游侠儿"]},{"text":"笼养之，昂其直，居为奇货。里胥猾黠，假此科敛丁口，每责一头，辄倾数","meaning":"第一部分（第1段），故事的起因","central":"笼养之，昂其直，居为奇货。","words":[],"markedWords":["笼","昂","其","直","为奇货","里胥","此","丁口","倾"]},{"text":"计营谋不能脱。不终岁，薄产累尽。会征促织，成不敢敛户口，而又无所赔","meaning":"围绕“计营谋不能脱”展开","central":"计营谋不能脱。","words":[],"markedWords":["薄产累","尽","户口"]},{"text":"偿，忧闷欲死。妻曰：“死何裨益？不如自行搜觅，冀有万一之得。”成然","meaning":"围绕“偿忧闷欲死”展开","central":"偿，忧闷欲死。","words":[],"markedWords":["裨益","然"]},{"text":"之。早出暮归，提竹筒铜丝笼，于败堵丛草处，探石发穴，靡计不施，迄无","meaning":"围绕“之”展开","central":"之。","words":[],"markedWords":["早","暮","败堵","计不施","无"]},{"text":"各种办法都用尽了，最终也没有成功（靡，无）。","meaning":"围绕“各种办法都用尽了最终”展","central":"各种办法都用尽了，最终也没有成功（靡，无）。","words":[],"markedWords":["各种办法都","用尽了","也没有"]},{"text":"济。即捕得三两头，又劣弱不中于款。宰严限追比，旬余，杖至百，两股间","meaning":"第二部分（第2段），故事的开端","central":"济。","words":[],"markedWords":["款","宰严限追比","杖"]},{"text":"脓血流离，并虫亦不能行捉矣。转侧床头，惟思自尽。","meaning":"围绕“脓血流离并虫亦不能行”展","central":"脓血流离，并虫亦不能行捉矣。","words":[],"markedWords":["流离","行"]},{"text":"唇吻翕辟，不知何词。各各竦立以听。少间，帘内掷一纸出，即道人意中事，","meaning":"围绕“唇吻翕辟不知何词”展开","central":"唇吻翕辟，不知何词。","words":[],"markedWords":["翕辟","竦立"]},{"text":"无毫发爽。成妻纳钱案上，焚拜如前人。食顷，帘动，片纸抛落。拾视之，","meaning":"围绕“无毫发爽”展开","central":"无毫发爽。","words":[],"markedWords":["无毫发爽","食顷"]},{"text":"非字而画：中绘殿阁，类兰若。后小山下，怪石乱卧，针针丛棘，青麻头伏","meaning":"围绕“非字而画中绘殿阁类兰”展","central":"非字而画：中绘殿阁，类兰若。","words":[],"markedWords":[]},{"text":"焉。旁一蟆，若将跳舞。展玩不可晓。然睹促织，隐中胸怀。折藏之，归以","meaning":"围绕“焉”展开","central":"焉。","words":[],"markedWords":[]}]},{"id":"docx_9","theme":0,"title":"谏太宗十思疏","author":"魏征〔唐代〕","genre":"古文","idea":"全文围绕“思国之安者，必积其德义 ”的主旨，规劝唐太宗在政治上要慎始敬终，虚心纳谏，赏罚公正；在 用人上要知人善任，简能择善；在生活上要戒奢以俭。这些主张以巩固李唐王朝统治为出发点，但客观上使人民生 活安定，有利于初唐的发展。","central":"臣闻求木之长者，必固其根本；","options":["全文围绕“思国之安者，必积其德义 ”的主旨，规劝唐太宗在政治上要慎始敬终，虚心纳谏，赏罚公正；在 用人上要知人善任，简能择善；在生活上要戒奢以俭。这些主张以巩固李唐王朝统治为出发点，但客观上使人民生 活安定，有利于初唐的发展。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"臣闻求木之长者，必固其根本；欲流之远者，必浚其泉源；思国之安者，","meaning":"开篇以常见之物、常识之理设喻，","central":"臣闻求木之长者，必固其根本；","words":[],"markedWords":["长","根本","浚"]},{"text":"必积其德义。源不深而望流之远，根不固而求木之长，德不厚而思国之理，","meaning":"围绕“必积其德义”展开","central":"必积其德义。","words":[],"markedWords":["德义"]},{"text":"臣虽下愚，知其不可，而况于明哲乎！人君当神器之重，居域中之大，将崇","meaning":"围绕“臣虽下愚知其不可而况”展","central":"臣虽下愚，知其不可，而况于明哲乎！","words":[],"markedWords":["下愚","明哲","神","器之重","居","之大"]},{"text":"胜其欲，斯亦伐根以求木茂，塞源而欲流长也。","meaning":"围绕“胜其欲斯亦伐根以求木”展","central":"胜其欲，斯亦伐根以求木茂，塞源而欲流长也。","words":[],"markedWords":[]},{"text":"凡百元首，承天景命，莫不殷忧而道著，功成而德衰。有善始者实繁，","meaning":"通过对历代帝王“有善始者实繁，","central":"凡百元首，承天景命，莫不殷忧而道著，功成而德衰。","words":[],"markedWords":["元首","承天","命","忧","实"]},{"text":"能克终者盖寡。岂取之易而守之难乎？昔取之而有余，今守之而不足，何也？","meaning":"围绕“能克终者盖寡”展开","central":"能克终者盖寡。","words":[],"markedWords":["能克终者","寡"]},{"text":"夫在殷忧，必竭诚以待下；既得志，则纵情以傲物。竭诚则胡越为一体，傲","meaning":"围绕“夫在殷忧必竭诚以待下”展","central":"夫在殷忧，必竭诚以待下；","words":[],"markedWords":["纵情","傲"]},{"text":"君人者，诚能见可欲则思知足以自戒，将有作则思知止以安人，念高","meaning":"明确提出人君只有做到“十思”，","central":"君人者，诚能见可欲则思知足以自戒，将有作则思知止以安人，念高","words":[],"markedWords":["见可欲","作","安","念高"]},{"text":"危则思谦冲而自牧，惧满溢则思江海下百川，乐盘游则思三驱以为度，忧懈","meaning":"围绕“危则思谦冲而自牧惧满”展","central":"危则思谦冲而自牧，惧满溢则思江海下百川，乐盘游则思三驱以为度，忧","words":[],"markedWords":["危则思","而自牧","满溢","江海","百川","盘游","三驱"]},{"text":"虑壅蔽则思虚心以纳下，想谗邪则思正身以黜恶，恩所","meaning":"围绕“虑壅蔽则思虚心以纳下”展","central":"虑壅蔽则思虚心以纳下，想谗邪则思正身以黜恶，恩所","words":[],"markedWords":["虑壅蔽","谗邪","黜"]},{"text":"能而任之，择善而从之，则智者尽其谋，勇者竭其力，仁者播其惠，信者效","meaning":"围绕“能而任之择善而从之则”展","central":"能而任之，择善而从之，则智者尽其谋，勇者竭其力，仁者播其惠，信者","words":[],"markedWords":["惠","信者"]}]},{"id":"docx_10","theme":0,"title":"答司马谏议书","author":"王安石〔宋代〕","genre":"古文","idea":"作为一篇驳论文，文章敏锐地把握住司马光五点责难的实质，点名其为名实之争，也就是政治主张的根本分 歧。答书逐条反驳，论证变法的正确性，揭示司马光责难的名不副实和因循守旧，在表明自己政治观点的同时，表 达出王安石坚持改革的意志和决心。","central":"某启：昨日蒙教，窃以为与君实游处相好之日久，而议事每不合，所操","options":["作为一篇驳论文，文章敏锐地把握住司马光五点责难的实质，点名其为名实之争，也就是政治主张的根本分 歧。答书逐条反驳，论证变法的正确性，揭示司马光责难的名不副实和因循守旧，在表明自己政治观点的同时，表 达出王安石坚持改革的意志和决心。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"某启：昨日蒙教，窃以为与君实游处相好之日久，而议事每不合，所操","meaning":"第1段，主要阐明写这封信的原因","central":"某启：昨日蒙教，窃以为与君实游处相好之日久，而议事每不合，所操","words":[],"markedWords":["蒙教","游处","每","所"]},{"text":"之术多异故也。虽欲强聒，终必不蒙见察，故略上报，不复一一自辨。重念","meaning":"围绕“之术多异故也”展开","central":"之术多异故也。","words":[],"markedWords":["之","强聒","不蒙见察","故","上报","辨","重念"]},{"text":"蒙君实视遇厚，于反覆不宜卤莽，故今具道所以，冀君实或见恕也。","meaning":"围绕“蒙君实视遇厚于反覆不”展","central":"蒙君实视遇厚，于反覆不宜卤莽，故今具道所以，冀君实或见恕也。","words":[],"markedWords":["视遇","反覆","卤莽","道","所以","冀"]},{"text":"盖儒者所争，尤在于名实，名实已明，而天下之理得矣。今君实所以见","meaning":"围绕“盖儒者所争尤在于名实”展","central":"盖儒者所争，尤在于名实，名实已明，而天下之理得矣。","words":[],"markedWords":["尤在于名实","天下之理得矣"]},{"text":"主，议法度而修之于朝廷，以授之于有司，不为侵官；举先王之政，以兴利","meaning":"围绕“主议法度而修之于朝廷”展","central":"主，议法度而修之于朝廷，以授之于有司，不为侵官；","words":[],"markedWords":["主","议法度","有司","不为","举"]},{"text":"除弊，不为生事；为天下理财，不为征利；辟邪说，难壬人，不为拒谏。至","meaning":"围绕“除弊不为生事”展开","central":"除弊，不为生事；","words":[],"markedWords":["邪说","壬人"]},{"text":"于怨诽之多，则固前知其如此也。","meaning":"第2段，作者先立后破，以“名实","central":"于怨诽之多，则固前知其如此也。","words":[],"markedWords":["前"]},{"text":"人习于苟且非一日，士大夫多以不恤国事、同俗自媚于众为善，上乃欲","meaning":"围绕“人习于苟且非一日士大”展","central":"人习于苟且非一日，士大夫多以不恤国事、同俗自媚于众为善，上乃欲","words":[],"markedWords":["苟且","恤","同俗自媚于众"]},{"text":"变此，而某不量敌之众寡，欲出力助上以抗之，则众何为而不汹汹然？盘庚","meaning":"围绕“变此而某不量敌之众寡”展","central":"变此，而某不量敌之众寡，欲出力助上以抗之，则众何为而不汹汹然？","words":[],"markedWords":["抗","汹汹然"]},{"text":"之迁，胥怨者民也，非特朝廷士大夫而已；盘庚不为怨者故改其度，度义而","meaning":"围绕“之迁胥怨者民也非特朝”展","central":"之迁，胥怨者民也，非特朝廷士大夫而已；","words":[],"markedWords":["胥怨","非特","度","而"]},{"text":"后动，是而不见可悔故也。如君实责我以在位久，未能助上大有为，以膏泽","meaning":"围绕“后动是而不见可悔故也”展","central":"后动，是而不见可悔故也。","words":[],"markedWords":["后动","是","可悔","膏泽"]},{"text":"斯民，则某知罪矣；如曰今日当一切不事事，守前所为而已，则非某之所敢","meaning":"围绕“斯民则某知罪矣”展开","central":"斯民，则某知罪矣；","words":[],"markedWords":["斯民","一切不","事","守前所为","所敢"]}]},{"id":"docx_11","theme":0,"title":"六国论","author":"苏洵〔宋代〕","genre":"古文","idea":"作者提出并论证了六国灭亡“弊在赂秦 ”的中心论点，借古讽今，抨击宋王朝对辽和西夏所采取的苟安政策， 告诫北宋统治者要吸取六国灭亡的教训，以免重蹈覆辙。","central":"或曰：六国互丧，率赂秦耶？","options":["作者提出并论证了六国灭亡“弊在赂秦 ”的中心论点，借古讽今，抨击宋王朝对辽和西夏所采取的苟安政策， 告诫北宋统治者要吸取六国灭亡的教训，以免重蹈覆辙。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"或曰：六国互丧，率赂秦耶？曰：不赂者以赂者丧，盖失强援，不能独完。","meaning":"围绕“或曰六国互丧率赂秦耶”展","central":"或曰：六国互丧，率赂秦耶？","words":[],"markedWords":["或曰","互丧","率","盖","完"]},{"text":"秦以攻取之外，小则获邑，大则得城。较秦之所得，与战胜而得者，其","meaning":"围绕“秦以攻取之外小则获邑”展","central":"秦以攻取之外，小则获邑，大则得城。","words":[],"markedWords":["以攻取","其"]},{"text":"视之不甚惜，举以予人，如弃草芥。今日割五城，明日割十城，然后得一夕","meaning":"本段论述向秦割地求和的韩、楚、","central":"视之不甚惜，举以予人，如弃草芥。","words":[],"markedWords":["视","举以予人","然后"]},{"text":"安寝。起视四境，而秦兵又至矣。然则诸侯之地有限，暴秦之欲无厌，奉之","meaning":"围绕“安寝”展开","central":"安寝。","words":[],"markedWords":["然则","厌","之"]},{"text":"弥繁，侵之愈急。故不战而强弱胜负已判矣。至于颠覆，理固宜然。古人云：","meaning":"围绕“弥繁侵之愈急”展开","central":"弥繁，侵之愈急。","words":[],"markedWords":["弥","侵之","急","判","颠覆","理","固宜然"]},{"text":"六国送给秦的越多，秦侵犯六国越厉害。","meaning":"围绕“六国送给秦的越多秦侵”展","central":"六国送给秦的越多，秦侵犯六国越厉害。","words":[],"markedWords":["六国送给秦的","秦侵","犯六国","厉害"]},{"text":"此言得之。这话说的很正确。此言得之。这话说的很正确。“以地事秦，犹抱薪救火，薪不尽，火不灭。”","meaning":"围绕“此言得之”展开","central":"此言得之。","words":[],"markedWords":["此言得之","这话说的很正确","事"]},{"text":"齐人未尝赂秦，终继五国迁灭，何哉？与嬴而不助五国也。五国既丧，","meaning":"围绕“齐人未尝赂秦终继五国”展","central":"齐人未尝赂秦，终继五国迁灭，何哉？","words":[],"markedWords":["终","迁灭","嬴","既"]},{"text":"齐亦不免矣。燕赵之君，始有远略，能守其土，义不赂秦。是故燕虽小国而","meaning":"围绕“齐亦不免矣”展开","central":"齐亦不免矣。","words":[],"markedWords":["免","远略","义"]},{"text":"三胜。后秦击赵者再，李牧连却之。洎牧以谗诛，邯郸为郡，惜其用武而不","meaning":"围绕“三胜”展开","central":"三胜。","words":[],"markedWords":["再","却","洎","以"]},{"text":"终也。且燕赵处秦革灭殆尽之际，可谓智力孤危，战败而亡，诚不得已。向","meaning":"围绕“终也”展开","central":"终也。","words":[],"markedWords":["殆","智力","向"]},{"text":"使三国各爱其地，齐人勿附于秦，刺客不行，良将犹在，则胜负之数，存亡","meaning":"围绕“使三国各爱其地齐人勿”展","central":"使三国各爱其地，齐人勿附于秦，刺客不行，良将犹在，则胜负之数，存","words":[],"markedWords":["使","胜负之数存亡"]}]},{"id":"docx_12","theme":1,"title":"论语十二章","author":"孔子及其弟子〔先秦〕","genre":"古文","idea":"从仁、义、礼、智、勇等诸方面，告诫学生要认真学习，勇于实践，遵守立身处世的规范性原则，体现了孔 子关于“君子 ”之德的看法和修身养性的基本观点。","central":"曰：“君子食无求饱，居无求安，敏于事而慎于言，就有道而正焉，可","options":["从仁、义、礼、智、勇等诸方面，告诫学生要认真学习，勇于实践，遵守立身处世的规范性原则，体现了孔 子关于“君子 ”之德的看法和修身养性的基本观点。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"曰：“君子食无求饱，居无求安，敏于事而慎于言，就有道而正焉，可","meaning":"围绕“曰君子食无求饱居无求”展","central":"曰：“君子食无求饱，居无求安，敏于事而慎于言，就有道而正焉，可","words":[],"markedWords":["敏","就有道而","正","焉"]},{"text":"子曰：“人而不仁，如礼何？人而不仁，如乐何？”(《八佾》)","meaning":"围绕“子曰人而不仁如礼何”展开","central":"子曰：“人而不仁，如礼何？","words":[],"markedWords":["而","如礼何"]},{"text":"子曰：“朝闻道，夕死可矣。”(《里仁》)","meaning":"围绕“子曰朝闻道夕死可矣”展开","central":"子曰：“朝闻道，夕死可矣。","words":[],"markedWords":[]},{"text":"子曰：“君子喻于义，小人喻于利。”(《里仁》)","meaning":"围绕“子曰君子喻于义小人喻”展","central":"子曰：“君子喻于义，小人喻于利。","words":[],"markedWords":["喻"]},{"text":"子曰：“见贤思齐焉，见不贤而内自省也。”(《里仁》)","meaning":"围绕“子曰见贤思齐焉见不贤”展","central":"子曰：“见贤思齐焉，见不贤而内自省也。","words":[],"markedWords":["贤","思","省"]},{"text":"曾子曰：“士不可以不弘毅，任重而道远。仁以为己任，不亦重乎？死","meaning":"围绕“曾子曰士不可以不弘毅”展","central":"曾子曰：“士不可以不弘毅，任重而道远。","words":[],"markedWords":["弘"]},{"text":"子曰：“知者不惑，仁者不忧，勇者不惧。”(《子罕》)","meaning":"围绕“子曰知者不惑仁者不忧”展","central":"子曰：“知者不惑，仁者不忧，勇者不惧。","words":[],"markedWords":["知"]},{"text":"颜渊问仁。子曰：“克己复礼为仁。一日克己复礼，天下归仁焉。","meaning":"围绕“颜渊问仁”展开","central":"颜渊问仁。","words":[],"markedWords":["克己复礼","一","日","归"]},{"text":"由己，而由人乎哉？”颜渊曰：“请问其目。”子曰：“非礼勿视，非礼勿","meaning":"围绕“由己而由人乎哉”展开","central":"由己，而由人乎哉？","words":[],"markedWords":["目"]},{"text":"听，非礼勿言，非礼勿动。”颜渊曰：“回虽不敏，请事斯语矣。”(《颜","meaning":"围绕“听非礼勿言非礼勿动”展开","central":"听，非礼勿言，非礼勿动。","words":[],"markedWords":["事"]},{"text":"子贡问曰：“有一言而可以终身行之者乎？”子曰：“其‘恕’乎！己","meaning":"论述处理人际关系的原则——己所","central":"子贡问曰：“有一言而可以终身行之者乎？","words":[],"markedWords":["一言","行","其‘恕","乎"]}]},{"id":"docx_13","theme":1,"title":"大学之道","author":"《礼记》〔两汉〕","genre":"古文","idea":"提出“三纲 ”“八目 ”，强调“修身 ”是根本，“修身 ”的目的是“治国 ”“平天下 ”，说明“治国 ”“平 天下 ”和加强个人品德修养的一致性。","central":"古之欲明明德于天下者，先治其国。","options":["提出“三纲 ”“八目 ”，强调“修身 ”是根本，“修身 ”的目的是“治国 ”“平天下 ”，说明“治国 ”“平 天下 ”和加强个人品德修养的一致性。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"古之欲明明德于天下者，先治其国。","meaning":"围绕“古之欲明明德于天下者”展","central":"古之欲明明德于天下者，先治其国。","words":[],"markedWords":[]},{"text":"欲治其国者，先齐其家。欲齐其家","meaning":"围绕“欲治其国者先齐其家”展开","central":"欲治其国者，先齐其家。","words":[],"markedWords":["齐","其家"]},{"text":"者，先修其身。欲修其身者，先正其心。欲正其心者，先诚其意。欲诚其意","meaning":"围绕“者先修其身”展开","central":"者，先修其身。","words":[],"markedWords":["修其身","正","诚"]},{"text":"者，先致其知。致知在格物。物格而后知至，知至而后意诚，意诚而后心正，","meaning":"围绕“者先致其知”展开","central":"者，先致其知。","words":[],"markedWords":["致其知","格物","知至"]},{"text":"心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。自天子以","meaning":"围绕“心正而后身修身修而后”展","central":"心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。","words":[],"markedWords":[]},{"text":"《礼记》：又名《小戴礼记》或《小戴记》，相传是由西汉礼学家戴圣编纂，共49篇，儒家经典之一，使秦汉以前各种礼仪论著的选集，是研究中国古代社会情况、儒家学说和文物制度的参考书。","meaning":"围绕“《礼记》又名《小戴礼”展","central":"《礼记》：又名《小戴礼记》或《小戴记》，相传是由西汉礼学家戴圣编纂，共49篇，儒家经典之一，使秦汉以前各种礼仪论著的选集，是研究中国古代社会情况、儒家学说和文物制度的参考书。","words":[],"markedWords":["《礼记》"]},{"text":"善用修辞。排比和反复的修辞的手法运用加强了语气，强调了观点，一方面使得文章整齐有序，具有音韵美；一方面将道理说得充分透彻，令人信服。顶真手法达到了环环相扣、引人入胜的目的，层层递进使得道理之间的联系更加紧密，增强了文章的说服力。","meaning":"围绕“善用修辞”展开","central":"善用修辞。","words":[],"markedWords":[]}]},{"id":"docx_14","theme":1,"title":"人皆有不忍人之心","author":"孟子〔先秦〕","genre":"古文","idea":"以“人皆有不忍人之心 ”发端，论述了“ 四心 ”“ 四端 ”以及两者的关系，最后提出人要懂得扩充“ 四端 ”， 从而阐明了人性本善，要求人们不断地扩充、发扬“ 四端 ”。","central":"以不忍人之心行不忍人之政，治天下可运之掌上。","options":["以“人皆有不忍人之心 ”发端，论述了“ 四心 ”“ 四端 ”以及两者的关系，最后提出人要懂得扩充“ 四端 ”， 从而阐明了人性本善，要求人们不断地扩充、发扬“ 四端 ”。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"以不忍人之心行不忍人之政，治天下可运之掌上。所以谓人皆有不忍人之心","meaning":"围绕“以不忍人之心行不忍人”展","central":"以不忍人之心行不忍人之政，治天下可运之掌上。","words":[],"markedWords":["运"]},{"text":"非人也；无羞恶之心，非人也；无辞让之心，非人也；无是非之心，非人也。","meaning":"围绕“非人也”展开","central":"非人也；","words":[],"markedWords":["辞让"]},{"text":"不善感到羞耻，对他人的不善感到憎恶）","meaning":"围绕“不善感到羞耻对他人的”展","central":"不善感到羞耻，对他人的不善感到憎恶）","words":[],"markedWords":[]},{"text":"恻隐之心，仁之端也；羞恶之心，义之端也；辞让之心，礼之端也；是非之","meaning":"围绕“恻隐之心仁之端也”展开","central":"恻隐之心，仁之端也；","words":[],"markedWords":["端"]},{"text":"心，智之端也。人之有是四端也，犹其有四体也。有是四端而自谓不能者，","meaning":"围绕“心智之端也”展开","central":"心，智之端也。","words":[],"markedWords":["四体"]},{"text":"若火之始然，泉之始达。苟能充之，足以保四海；苟不充之，不足以事父","meaning":"围绕“若火之始然泉之始达”展开","central":"若火之始然，泉之始达。","words":[],"markedWords":["然","达","保"]},{"text":"《孟子》：是记载孟子及其弟子的政治、教育、哲学、伦理等思想观点和政治活动的著作，现存7篇，一般认为是孟子及其弟子万章等著。宋代把它与《大学》《中庸》《论语》合为“四书”。","meaning":"围绕“《孟子》是记载孟子及”展","central":"《孟子》：是记载孟子及其弟子的政治、教育、哲学、伦理等思想观点和政治活动的著作，现存7篇，一般认为是孟子及其弟子万章等著。","words":[],"markedWords":["《孟子》"]},{"text":"运用比喻，使抽象的道理变得通俗易懂。如“以不忍人之心行不忍人之政，治天下可运之掌上”，将用“不忍人之政”治理天下比作在手掌上运转东西，突出表现“不忍人之政”治理天下的容易，使道理具体、贴切。","meaning":"围绕“运用比喻使抽象的道理”展","central":"运用比喻，使抽象的道理变得通俗易懂。","words":[],"markedWords":[]},{"text":"运用排比，层次清楚。如“无恻隐之心，非人也……无是非之心，非人也”，运用排比，既严密地展开了论述，又增强了语势。","meaning":"围绕“运用排比层次清楚”展开","central":"运用排比，层次清楚。","words":[],"markedWords":[]},{"text":"举例论证，形象生动，使人容易接受。如论证“人皆有不忍人之心”时，以“今人乍见孺子将入于井”为例展开论述，由此生动形象地引出人有“四心”和“四端”的观点。","meaning":"围绕“举例论证形象生动使人”展","central":"举例论证，形象生动，使人容易接受。","words":[],"markedWords":[]}]},{"id":"docx_15","theme":1,"title":"五石之瓠","author":"庄子〔先秦〕","genre":"古文","idea":"选文采用问答形式，讲述了“大瓠无用 ”和“不龟手之药 ”两个故事，揭示了万物皆有所用，同样一件东西， 由于人们的眼光不同，它所发挥的作用也不一样。同时，也体现了庄子的思想和道家的哲学。","central":"惠子谓庄子曰：“魏王贻我大瓠之种，我树之成而实五石。","options":["选文采用问答形式，讲述了“大瓠无用 ”和“不龟手之药 ”两个故事，揭示了万物皆有所用，同样一件东西， 由于人们的眼光不同，它所发挥的作用也不一样。同时，也体现了庄子的思想和道家的哲学。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"惠子谓庄子曰：“魏王贻我大瓠之种，我树之成而实五石。","meaning":"围绕“惠子谓庄子曰魏王贻我”展","central":"惠子谓庄子曰：“魏王贻我大瓠之种，我树之成而实五石。","words":[],"markedWords":["树","实五石"]},{"text":"絖，不过数金；今一朝而鬻技百金，请与之。’客得之，以说吴王。越有难，","meaning":"围绕“絖不过数金”展开","central":"絖，不过数金；","words":[],"markedWords":["鬻","请","说","越","有难"]},{"text":"吴王使之将，冬，与越人水战，大败越人，裂地而封之。能不龟手一也，或","meaning":"第二层，借“不龟手之药”的故事","central":"吴王使之将，冬，与越人水战，大败越人，裂地而封之。","words":[],"markedWords":["将","冬","裂","一","或"]},{"text":"这与道家认为人生命存在的本身是有价值的，不能为外物牺牲的思想相契合。以封，或不免于洴澼絖，则所用之异也。今子有五石之瓠，何不虑以为","meaning":"第三层，写“浮乎江湖”，揭示主","central":"这与道家认为人生命存在的本身是有价值的，不能为外物牺牲的思想相契合。","words":[],"markedWords":["虑"]},{"text":"大樽而浮乎江湖，而忧其瓠落无所容？","meaning":"围绕“大樽而浮乎江湖而忧其”展","central":"大樽而浮乎江湖，而忧其瓠落无所容？","words":[],"markedWords":["樽"]},{"text":"运动对话描写刻画人物。文章的思想是靠人物对话传达出来的，惠子和庄子互相辩驳，惠子用瓠大而无用的例子来影射庄子的学说大而不实用；而庄子用宋人擅长制作防止手冻裂的药物却只能漂洗丝絮，而买宋人药房的人却用这个药方得到封赏的例子，来说明同一事物因“所用之异”故价值也不同的道理，并指出惠子见识的不通达。","meaning":"围绕“运动对话描写刻画人物”展","central":"运动对话描写刻画人物。","words":[],"markedWords":[]},{"text":"善于使讽刺与剖析结合，将道家的“生命存在的本身是有价值的”这一观点表达得淋漓尽致。","meaning":"围绕“善于使讽刺与剖析结合”展","central":"善于使讽刺与剖析结合，将道家的“生命存在的本身是有价值的”这一观点表达得淋漓尽致。","words":[],"markedWords":[]}]},{"id":"docx_16","theme":1,"title":"兼爱","author":"墨子〔先秦〕","genre":"古文","idea":"“兼爱 ”是墨家的核心主张之一。本文认为天下的祸乱都起于“不爱 ”。父与子、兄与弟、君与臣，如果爱 自己而不爱对方、亏人而自利，就会天下动乱；盗贼爱自己而不爱他人，因此盗窃和残害别人；诸侯和卿大夫爱其 国与其封地，而不爱他人之国与他人之封地，故互相攻打和扰乱。若使天下兼相爱，爱人如己，窃夺攻伐的现象得 以消除，天下就会安定太平。写作特色（语言）：文章质朴，不重文采：文辞不加修饰，就近取譬，浅显易懂，重在以理服人。逻辑严密，明辨是非：本文先指出议论的焦点“圣人以治天下为事者也，必知乱之所自起 ”；接着从三个方面分别 论述祸乱“ 皆起不相爱 ”；然后通过对比论证，说明“天下兼相爱 ”“则天下治 ”；最后顺理成章得出“天下兼相 爱则治，交相恶则乱 ”的结论。论辩一气呵成，逻辑严密，富于说服力。","central":"之所自起，则弗能攻。","options":["“兼爱 ”是墨家的核心主张之一。本文认为天下的祸乱都起于“不爱 ”。父与子、兄与弟、君与臣，如果爱 自己而不爱对方、亏人而自利，就会天下动乱；盗贼爱自己而不爱他人，因此盗窃和残害别人；诸侯和卿大夫爱其 国与其封地，而不爱他人之国与他人之封地，故互相攻打和扰乱。若使天下兼相爱，爱人如己，窃夺攻伐的现象得 以消除，天下就会安定太平。写作特色（语言）：文章质朴，不重文采：文辞不加修饰，就近取譬，浅显易懂，重在以理服人。逻辑严密，明辨是非：本文先指出议论的焦点“圣人以治天下为事者也，必知乱之所自起 ”；接着从三个方面分别 论述祸乱“ 皆起不相爱 ”；然后通过对比论证，说明“天下兼相爱 ”“则天下治 ”；最后顺理成章得出“天下兼相 爱则治，交相恶则乱 ”的结论。论辩一气呵成，逻辑严密，富于说服力。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"之所自起，则弗能攻。治乱者何独不然？必知乱之所自起，焉能治之；不知","meaning":"围绕“之所自起则弗能攻”展开","central":"之所自起，则弗能攻。","words":[],"markedWords":["然"]},{"text":"不爱兄，故亏兄而自利；臣自爱，不爱君，故亏君而自利，此所谓乱也。虽","meaning":"围绕“不爱兄故亏兄而自利”展开","central":"不爱兄，故亏兄而自利；","words":[],"markedWords":["虽"]},{"text":"父之不慈子，兄之不慈弟，君之不慈臣，此亦天下之所谓乱也。父自爱也，","meaning":"围绕“父之不慈子兄之不慈弟”展","central":"父之不慈子，兄之不慈弟，君之不慈臣，此亦天下之所谓乱也。","words":[],"markedWords":["慈"]},{"text":"不爱子，故亏子而自利；兄自爱也，不爱弟，故亏弟而自利；君自爱也，不","meaning":"围绕“不爱子故亏子而自利”展开","central":"不爱子，故亏子而自利；","words":[],"markedWords":[]},{"text":"爱臣，故亏臣而自利。是何也？皆起不相爱。虽至天下之为盗贼者，亦然，","meaning":"围绕“爱臣故亏臣而自利”展开","central":"爱臣，故亏臣而自利。","words":[],"markedWords":["盗贼"]},{"text":"盗爱其室，不爱其异室，故窃异室以利其室；贼爱其身，不爱人，故贼人以","meaning":"围绕“盗爱其室不爱其异室故”展","central":"盗爱其室，不爱其异室，故窃异室以利其室；","words":[],"markedWords":["室","利","不","爱人","贼"]},{"text":"利其身。此何也？皆起不相爱。虽至大夫之相乱家，诸侯之相攻国者，亦然。","meaning":"围绕“利其身”展开","central":"利其身。","words":[],"markedWords":["家"]},{"text":"大夫各爱其家，不爱异家，故乱异家以利其家；诸侯各爱其国，不爱异国，","meaning":"围绕“大夫各爱其家不爱异家”展","central":"大夫各爱其家，不爱异家，故乱异家以利其家；","words":[],"markedWords":["异家","其家"]},{"text":"故攻异国以利其国，天下之乱物，具此而已矣。","meaning":"围绕“故攻异国以利其国天下”展","central":"故攻异国以利其国，天下之乱物，具此而已矣。","words":[],"markedWords":["乱物","此"]},{"text":"察此何自起？皆起不相爱。若使天下兼相爱，爱人若爱其身，犹有不孝","meaning":"围绕“察此何自起”展开","central":"察此何自起？","words":[],"markedWords":["若","若爱其身","犹"]},{"text":"者乎？视父兄与君若其身，恶施不孝？犹有不慈者乎？视弟子与臣若其身，","meaning":"围绕“者乎”展开","central":"者乎？","words":[],"markedWords":["视","施"]},{"text":"恶施不慈？故不孝不慈亡。犹有盗贼乎？视人之室若其室，谁窃？视人身若","meaning":"围绕“恶施不慈”展开","central":"恶施不慈？","words":[],"markedWords":["亡"]}]},{"id":"docx_17","theme":2,"title":"屈原列传","author":"司马迁〔两汉〕","genre":"古文","idea":"本文通过写屈原的生平事迹，特别是政治上的不幸遭遇，将屈原的生死与楚国的兴衰存亡对照来写，凸显了 屈原对楚国的价值和意义，赞扬了他的爱国主义精神和正直的品德，处处流露出作者的郁郁不平之气和“悲其志 ” 的叹惋。","central":"说人品行不正的小人损害国家，端方正直的人不被","options":["本文通过写屈原的生平事迹，特别是政治上的不幸遭遇，将屈原的生死与楚国的兴衰存亡对照来写，凸显了 屈原对楚国的价值和意义，赞扬了他的爱国主义精神和正直的品德，处处流露出作者的郁郁不平之气和“悲其志 ” 的叹惋。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"说人品行不正的小人损害国家，端方正直的人不被","meaning":"围绕“说人品行不正的小人损”展","central":"说人品行不正的小人损害国家，端方正直的人不被","words":[],"markedWords":["说人","的人不被"]},{"text":"坏话、奉承谄媚的小人混淆黑白，蒙蔽怀王。昏君谗臣所容，","meaning":"围绕“坏话、奉承谄媚的小人”展","central":"坏话、奉承谄媚的小人混淆黑白，蒙蔽怀王。","words":[],"markedWords":["昏君谗臣所容"]},{"text":"离骚”者，犹离忧也。夫天者，人之始也；父","meaning":"围绕“离骚者犹离忧也”展开","central":"离骚”者，犹离忧也。","words":[],"markedWords":["忧"]},{"text":"母者，人之本也。人穷则反本，故劳苦倦极，未尝不呼天也；疾痛惨怛，未","meaning":"围绕“母者人之本也”展开","central":"母者，人之本也。","words":[],"markedWords":["人穷则","本","倦","惨怛"]},{"text":"屈平正道直行，竭忠尽智以事其君，","meaning":"围绕“屈平正道直行竭忠尽智”展","central":"屈平正道直行，竭忠尽智以事其君，","words":[],"markedWords":[]},{"text":"信而见疑，忠而被谤，能无怨乎？屈平之作《离骚》，盖自怨生也。《国风》","meaning":"围绕“信而见疑忠而被谤能无”展","central":"信而见疑，忠而被谤，能无怨乎？","words":[],"markedWords":["信而","疑","盖自怨生也","《国风》"]},{"text":"好色而不淫，《小雅》怨诽而不乱。若《离骚》者，可谓兼之矣。上称帝喾，","meaning":"围绕“好色而不淫《小雅》怨”展","central":"好色而不淫，《小雅》怨诽而不乱。","words":[],"markedWords":["好色而不","兼之","上称帝喾"]},{"text":"《国风》好描写男女恋情但不失分寸（过度、无节制），《小雅》怨愤发牢骚但不坏乱礼法。","meaning":"围绕“《国风》好描写男女恋”展","central":"《国风》好描写男女恋情但不失分寸（过度、无节制），《小雅》怨愤发牢骚但不坏乱礼法。","words":[],"markedWords":[]},{"text":"用古代帝王这些事用来讥刺当世的事。","meaning":"围绕“用古代帝王这些事用来”展","central":"用古代帝王这些事用来讥刺当世的事。","words":[],"markedWords":["当世的事"]},{"text":"举的事例浅近，但是表达意思很深远。","meaning":"围绕“举的事例浅近但是表达”展","central":"举的事例浅近，但是表达意思很深远。","words":[],"markedWords":["举的","但是","意思很深远"]},{"text":"其志洁，故其称物芳；其行廉，故死而不容。自疏濯淖污泥之中，蝉蜕于浊","meaning":"（第1-3段）屈原文化修养深厚","central":"其志洁，故其称物芳；","words":[],"markedWords":["称物芳","故死而不容","自疏","之","中","于"]},{"text":"所以至死不容他自动地远离污浊，像蝉脱壳那样摆脱污","meaning":"围绕“所以至死不容他自动地”展","central":"所以至死不容他自动地远离污浊，像蝉脱壳那样摆脱污","words":[],"markedWords":["所以至死不容","他自动地远离","摆脱"]}]},{"id":"docx_18","theme":2,"title":"苏武传","author":"班固〔两汉〕","genre":"古文","idea":"刻画了苏武这一不朽的爱国者的形象，通过许多生动具体的细节描写，再现了他作为汉史被无理扣留匈奴后， 十九年间始终不被威服、不被利诱，艰苦卓绝、视死如归的感人事迹，讴歌了其坚贞不屈的民族气节和忠心耿耿的 高尚品质","central":"留之以相当。","options":["刻画了苏武这一不朽的爱国者的形象，通过许多生动具体的细节描写，再现了他作为汉史被无理扣留匈奴后， 十九年间始终不被威服、不被利诱，艰苦卓绝、视死如归的感人事迹，讴歌了其坚贞不屈的民族气节和忠心耿耿的 高尚品质","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"留之以相当。天汉元年，且鞮侯单于初立，恐汉袭之，乃曰：“汉天子我丈","meaning":"围绕“留之以相当”展开","central":"留之以相当。","words":[],"markedWords":["相当","汉天","子我","丈"]},{"text":"人行也。”尽归汉使路充国等。武帝嘉其义，乃遣武以中郎将使持节送匈奴","meaning":"围绕“人行也”展开","central":"人行也。","words":[],"markedWords":["人","也","嘉其","送匈奴"]},{"text":"子也，与昆邪王俱降汉，后随浞野侯没胡中。及卫律所将降者，阴谋劫","meaning":"相与","central":"子也，与昆邪王俱降汉，后随浞野侯没胡中。","words":[],"markedWords":["后随浞野侯","胡中","及卫律所","降者","谋劫"]},{"text":"“闻汉天子甚怨卫律，常能为汉伏弩射杀之，吾母与弟在汉，幸其赏赐。”","meaning":"蒙","central":"“闻汉天子甚怨卫律，常能为汉伏弩射杀之，吾母与弟在汉，幸其赏赐。","words":[],"markedWords":["常能为汉","射杀之","其赏赐"]},{"text":"3后月余，单于出猎，独阏氏子弟在。虞常等七十余人欲发，其一人夜亡，","meaning":"围绕“3后月余单于出猎独阏”展","central":"3后月余，单于出猎，独阏氏子弟在。","words":[],"markedWords":["独阏氏子弟在","发","亡"]},{"text":"告之。单于子弟发兵与战，缑王等皆死，虞常生得。单于使卫律治其事，张","meaning":"围绕“告之”展开","central":"告之。","words":[],"markedWords":["告","生得","治其事"]},{"text":"胜闻之，恐前语发，以状语武。武曰：“事如此，此必及我，见犯乃死，重","meaning":"围绕“胜闻之恐前语发以状语”展","central":"胜闻之，恐前语发，以状语武。","words":[],"markedWords":["恐前语","以","语武","及","见犯乃死"]},{"text":"负国。”欲自杀，胜、惠共止之。虞常果引张胜。单于怒，召诸贵人议，欲","meaning":"围绕“负国”展开","central":"负国。","words":[],"markedWords":["负国","引","贵人"]},{"text":"杀汉使者。左伊秩訾曰：“即谋单于，何以复加？宜皆降之。”","meaning":"围绕“杀汉使者”展开","central":"杀汉使者。","words":[],"markedWords":["即谋单于","何以复加","宜皆","之"]},{"text":"5武益愈，单于使使晓武，会论虞常，欲因此时降武。剑斩虞常已，律曰：","meaning":"围绕“5武益愈单于使使晓武”展","central":"5武益愈，单于使使晓武，会论虞常，欲因此时降武。","words":[],"markedWords":["愈","晓","会","虞常","因此"]},{"text":"律谓武曰：“副有罪，当相坐。”武曰：“本无谋，又非亲属，何谓相坐？”","meaning":"围绕“律谓武曰副有罪当相坐”展","central":"律谓武曰：“副有罪，当相坐。","words":[],"markedWords":["相坐","本无谋","何谓相坐"]},{"text":"复举剑拟之，武不动。律曰：“苏君，律前负汉归匈奴，幸蒙大恩，赐号称","meaning":"围绕“复举剑拟之武不动”展开","central":"复举剑拟之，武不动。","words":[],"markedWords":["之"]}]},{"id":"docx_19","theme":3,"title":"过秦论","author":"贾谊〔两汉〕","genre":"古文","idea":"文章通过概括从秦 孝公到秦亡国的历史 ，说 明了秦朝由兴起到灭亡的 全过程，分析总结了秦朝 灭亡的原因，阐述了作者 关于治国应施行仁义的主 张 。作者的写作目的是希 望汉朝以秦为借鉴 ，施行 仁义，对百姓实行宽松政 策，谋求长治久安之道。","central":"1秦孝公据崤函之固，拥雍州之地，君臣固守以窥周室，有席卷天下，包","options":["文章通过概括从秦 孝公到秦亡国的历史 ，说 明了秦朝由兴起到灭亡的 全过程，分析总结了秦朝 灭亡的原因，阐述了作者 关于治国应施行仁义的主 张 。作者的写作目的是希 望汉朝以秦为借鉴 ，施行 仁义，对百姓实行宽松政 策，谋求长治久安之道。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"1秦孝公据崤函之固，拥雍州之地，君臣固守以窥周室，有席卷天下，包","meaning":"围绕“1秦孝公据崤函之固拥”展","central":"1秦孝公据崤函之固，拥雍州之地，君臣固守以窥周室，有席卷天下，包","words":[],"markedWords":["崤函","有","天下"]},{"text":"举宇内，囊括四海之意，并吞八荒之心。当是时也，商君佐之，内立法度，","meaning":"围绕“举宇内囊括四海之意并”展","central":"举宇内，囊括四海之意，并吞八荒之心。","words":[],"markedWords":["宇内","内"]},{"text":"务耕织，修守战之具，外连衡而斗诸侯。于是秦人拱手而取西河之外。","meaning":"围绕“务耕织修守战之具外连”展","central":"务耕织，修守战之具，外连衡而斗诸侯。","words":[],"markedWords":["连衡","拱手"]},{"text":"2孝公既没，惠文、武、昭襄蒙故业，因遗策，南取汉中，西举巴、蜀，","meaning":"围绕“2孝公既没惠文、武、”展","central":"2孝公既没，惠文、武、昭襄蒙故业，因遗策，南取汉中，西举巴、蜀，","words":[],"markedWords":["没","故业因遗策"]},{"text":"东割膏腴之地，北收要害之郡。诸侯恐惧，会盟而谋弱秦，不爱珍器重宝肥","meaning":"围绕“东割膏腴之地北收要害”展","central":"东割膏腴之地，北收要害之郡。","words":[],"markedWords":["要害之郡","弱","爱"]},{"text":"饶之地，以致天下之士，合从缔交，相与为一。当此之时，齐有孟尝，赵有","meaning":"围绕“饶之地以致天下之士合”展","central":"饶之地，以致天下之士，合从缔交，相与为一。","words":[],"markedWords":["致","合从缔交相与为一"]},{"text":"平原，楚有春申，魏有信陵。此四君者，皆明智而忠信，宽厚而爱人，尊贤","meaning":"围绕“平原楚有春申魏有信陵”展","central":"平原，楚有春申，魏有信陵。","words":[],"markedWords":[]},{"text":"六国之士，有甯越、徐尚、苏秦、杜赫之属为之谋，齐明、周最、陈轸、召","meaning":"围绕“六国之士有甯越、徐尚”展","central":"六国之士，有甯越、徐尚、苏秦、杜赫之属为之谋，齐明、周最、陈轸、","words":[],"markedWords":[]},{"text":"滑、楼缓、翟景、苏厉、乐毅之徒通其意，吴起、孙膑、带佗、倪良、王廖、","meaning":"围绕“滑、楼缓、翟景、苏厉”展","central":"滑、楼缓、翟景、苏厉、乐毅之徒通其意，吴起、孙膑、带佗、倪良、王","words":[],"markedWords":["通其意"]},{"text":"田忌、廉颇、赵奢之伦制其兵。尝以十倍之地，百万之众，叩关而攻秦。秦","meaning":"围绕“田忌、廉颇、赵奢之伦”展","central":"田忌、廉颇、赵奢之伦制其兵。","words":[],"markedWords":["其兵","叩关"]},{"text":"人开关延敌，九国之师，逡巡而不敢进。秦无亡矢遗镞之费，而天下诸侯已","meaning":"秦国势力得到进一步扩张。用高度","central":"人开关延敌，九国之师，逡巡而不敢进。","words":[],"markedWords":["延敌","逡巡","镞"]}]},{"id":"docx_20","theme":3,"title":"五代史伶官传序","author":"欧阳修〔宋代〕","genre":"古文","idea":"通对五代时期的后唐庄宗得天下与失天的历史教训的分析，得出“忧劳可以兴国，逸豫可以亡身 ”和“祸患 常积于忽微，而智勇多困于所溺 ”的结论，说明国家兴衰不取决于天命，而取决于“人事 ”，借以告诫当时北宋的 执政者要吸取历史教训，居安思危，防微杜渐。","central":"成功：动词用作名词，成功的消息","options":["通对五代时期的后唐庄宗得天下与失天的历史教训的分析，得出“忧劳可以兴国，逸豫可以亡身 ”和“祸患 常积于忽微，而智勇多困于所溺 ”的结论，说明国家兴衰不取决于天命，而取决于“人事 ”，借以告诫当时北宋的 执政者要吸取历史教训，居安思危，防微杜渐。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"成功：动词用作名词，成功的消息","meaning":"围绕“成功动词用作名词成功”展","central":"成功：动词用作名词，成功的消息","words":[],"markedWords":[]},{"text":"33方其系燕父子以组，函梁君臣之首，入于太庙，还矢先王，而告以成功，","meaning":"围绕“33方其系燕父子以组”展","central":"33方其系燕父子以组，函梁君臣之首，入于太庙，还矢先王，而告以成","words":[],"markedWords":["方","系","函","成功"]},{"text":"其意气之盛，可谓壮哉！及仇雠已灭，天下已定，一夫夜呼，乱者四应，仓","meaning":"围绕“其意气之盛可谓壮哉”展开","central":"其意气之盛，可谓壮哉！","words":[],"markedWords":["仇雠","一夫","呼","者","应"]},{"text":"皇东出，未及见贼而士卒离散，君臣相顾，不知所归，至于誓天断发，泣下","meaning":"围绕“皇东出未及见贼而士卒”展","central":"皇东出，未及见贼而士卒离散，君臣相顾，不知所归，至于誓天断发，泣","words":[],"markedWords":["东","顾","泣"]},{"text":"沾襟，何其衰也！岂得之难而失之易欤？抑本其成败之迹，而皆自于人欤？","meaning":"围绕“沾襟何其衰也”展开","central":"沾襟，何其衰也！","words":[],"markedWords":["抑","皆自于人欤"]},{"text":"《书》曰：“满招损，谦得益。”忧劳可以兴国，逸豫可以亡身，自然之理","meaning":"围绕“《书》曰满招损谦得益”展","central":"《书》曰：“满招损，谦得益。","words":[],"markedWords":["兴","逸豫","亡"]},{"text":"44故方其盛也，举天下之豪杰，莫能与之争；及其衰也，数十伶人困之，","meaning":"围绕“44故方其盛也举天下”展","central":"44故方其盛也，举天下之豪杰，莫能与之争；","words":[],"markedWords":["举","数十伶人困之"]},{"text":"语气词连用，表示反诘语气。语气词连用，表示反诘语气。欧阳修：1007-1072，字永叔，号醉翁、六一居士，","meaning":"围绕“语气词连用表示反诘语”展","central":"语气词连用，表示反诘语气。","words":[],"markedWords":["欧阳修"]},{"text":"“唐宋八大家”之一。政治上曾支持范仲淹领导的政治改革；文学上主张文章应“明道”“致用”，","meaning":"围绕“唐宋八大家之一”展开","central":"“唐宋八大家”之一。","words":[],"markedWords":[]},{"text":"5353对宋以来靡丽、险怪的文风表示不满，使北宋古文运动的领袖。散文说理畅达，抒情委婉；诗受李白、韩愈影响，重气势而能流畅自然；词风婉丽，承袭南唐余风。","meaning":"围绕“5353对宋以来靡丽”展","central":"5353对宋以来靡丽、险怪的文风表示不满，使北宋古文运动的领袖。","words":[],"markedWords":[]}]},{"id":"docx_21","theme":2,"title":"离骚","author":"屈原〔先秦〕","genre":"古文","idea":"。诗人先从自己的出身、政治理想和政治遭遇写起，接着否决自己隐退的念头，表明自己九死未悔、体解未 变、忧国忧民的爱国热情，彰显了其不与小人同流合污的高洁品质和不屈不挠的斗争精神。","central":"纷吾既有此内美兮，又重之以修能。","options":["。诗人先从自己的出身、政治理想和政治遭遇写起，接着否决自己隐退的念头，表明自己九死未悔、体解未 变、忧国忧民的爱国热情，彰显了其不与小人同流合污的高洁品质和不屈不挠的斗争精神。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"纷吾既有此内美兮，又重之以修能。扈江离与辟芷兮，纫秋兰以为佩。","meaning":"围绕“纷吾既有此内美兮又重”展","central":"纷吾既有此内美兮，又重之以修能。","words":[],"markedWords":["纷","重","修能","扈","辟","纫"]},{"text":"忽其不淹兮，春与秋其代序。惟草木之零落兮，恐美人之迟暮。不抚壮而弃","meaning":"围绕“忽其不淹兮春与秋其代”展","central":"忽其不淹兮，春与秋其代序。","words":[],"markedWords":["淹","代序","惟","零落","迟暮","抚","弃"]},{"text":"秽兮，何不改乎此度？乘骐骥以驰骋兮，来吾道夫先路！","meaning":"围绕“秽兮何不改乎此度”展开","central":"秽兮，何不改乎此度？","words":[],"markedWords":["秽","道","先路"]},{"text":"长太息以掩涕兮，哀民生之多艰。余虽好修姱以鞿羁兮，謇朝谇而夕替。","meaning":"围绕“长太息以掩涕兮哀民生”展","central":"长太息以掩涕兮，哀民生之多艰。","words":[],"markedWords":["太息","民生","好","鞿羁","谇","替"]},{"text":"既替余以蕙纕兮，又申之以揽茝。亦余心之所善兮，虽九死其犹未悔。怨灵","meaning":"围绕“既替余以蕙纕兮又申之”展","central":"既替余以蕙纕兮，又申之以揽茝。","words":[],"markedWords":["纕","申","善","悔"]},{"text":"修之浩荡兮，终不察夫民心。众女嫉余之蛾眉兮，谣诼谓余以善淫。固时俗","meaning":"围绕“修之浩荡兮终不察夫民”展","central":"修之浩荡兮，终不察夫民心。","words":[],"markedWords":["浩荡","民心","众女","蛾眉","谣诼","固"]},{"text":"之工巧兮，偭规矩而改错。背绳墨以追曲兮，竞周容以为度。忳郁邑余侘傺","meaning":"围绕“之工巧兮偭规矩而改错”展","central":"之工巧兮，偭规矩而改错。","words":[],"markedWords":["工巧","错","绳墨","追曲","周容","忳郁邑","侘傺"]},{"text":"兮，吾独穷困乎此时也。宁溘死以流亡兮，余不忍为此态也！","meaning":"围绕“兮吾独穷困乎此时也”展开","central":"兮，吾独穷困乎此时也。","words":[],"markedWords":["穷困","溘","流亡","此态"]},{"text":"自前世而固然。何方圜之能周兮，夫孰异道而相安？","meaning":"围绕“自前世而固然”展开","central":"自前世而固然。","words":[],"markedWords":["前世","固然","方","圜","周","孰"]},{"text":"攘诟。伏清白以死直兮，固前圣之所厚。","meaning":"围绕“攘诟”展开","central":"攘诟。","words":[],"markedWords":["攘","伏","死","直","厚"]},{"text":"悔相道之不察兮，延伫乎吾将反。回朕车以复路兮，及行迷之未远。步","meaning":"围绕“悔相道之不察兮延伫乎”展","central":"悔相道之不察兮，延伫乎吾将反。","words":[],"markedWords":["相","延伫","复路","及","步"]},{"text":"余马于兰皋兮，驰椒丘且焉止息。进不入以离尤兮，退将复修吾初服。制芰","meaning":"围绕“余马于兰皋兮驰椒丘且”展","central":"余马于兰皋兮，驰椒丘且焉止息。","words":[],"markedWords":["皋","丘","焉","不入","离","初服","芰"]}]},{"id":"docx_22","theme":4,"title":"陈情表","author":"李密〔魏晋〕","genre":"古文","idea":"作者主要申诉自己不能应招的苦衷，从自己幼年的不幸遭遇写起，表达自己与祖母相依为命的特殊感情，言 辞极其恳切、极其动人。","central":"臣密今年四十有四，祖母今年九十有六，是臣尽节于陛下之日长，报养","options":["作者主要申诉自己不能应招的苦衷，从自己幼年的不幸遭遇写起，表达自己与祖母相依为命的特殊感情，言 辞极其恳切、极其动人。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"臣密今年四十有四，祖母今年九十有六，是臣尽节于陛下之日长，报养","meaning":"作者从情、理两方面写，写得娓娓","central":"臣密今年四十有四，祖母今年九十有六，是臣尽节于陛下之日长，报养","words":[],"markedWords":[]},{"text":"见明知，皇天后土实所共鉴。愿陛下矜愍愚诚，听臣微志，庶刘侥幸，保卒","meaning":"围绕“见明知皇天后土实所共”展","central":"见明知，皇天后土实所共鉴。","words":[],"markedWords":["见明知","皇天后土实所共","矜愍","听","刘侥幸保卒"]},{"text":"余年。臣生当陨首，死当结草。臣不胜犬马怖惧之情，谨拜表以闻。","meaning":"围绕“余年”展开","central":"余年。","words":[],"markedWords":["余年","死当结草","犬马","怖惧之情","拜表"]},{"text":"李密：224-287，一名虔，字令伯，犍为武阳（今四川彭山）人。幼年丧父，母亲改嫁，由祖母抚养成人。后李密对祖母孝敬甚笃而名扬于乡里。李密师从当时的著名学者谯周，博览五经，尤精《左传》。李密在蜀汉任郎中和尚书郎。蜀汉亡，晋武帝征召他任太子洗马时，李密以祖母年老多病、无人供养而力辞。祖母去世后，方出任太子洗马。后免官，卒于家中。","meaning":"围绕“李密224-287一”展","central":"李密：224-287，一名虔，字令伯，犍为武阳（今四川彭山）人。","words":[],"markedWords":["李密"]},{"text":"《陈情表》：李密作品大都遗失，流传至今的只有《陈情表》和《赐饯东堂诏令赋诗》。《陈情表》本于宗法人伦之至常，措辞委婉，无一字虚言藻饰，情真意切，感人至深，一向为世人所传诵。史载当年晋武帝读了此表之后，深受感动，下诏李密留养祖母，并赐奴婢两人，使其所在郡县供养其祖母奉膳。","meaning":"围绕“《陈情表》李密作品大”展","central":"《陈情表》：李密作品大都遗失，流传至今的只有《陈情表》和《赐饯东堂诏令赋诗》。","words":[],"markedWords":["《陈情表》"]},{"text":"文章采取了“以子之矛陷子之盾”的论证方式。作为亡国之臣的李密无法奉诏，理由只是奉亲，并不是与新朝对立，更不是为蜀汉保守名节。只此一点就直接将奉亲与奉诏对立起来。另外，如果晋武帝一定要李密任太子洗马，则李密不能奉亲从而违背了晋朝“以孝治天下”的治国理念，也使晋武帝陷入了前后矛盾的境地。","meaning":"围绕“文章采取了以子之矛陷”展","central":"文章采取了“以子之矛陷子之盾”的论证方式。","words":[],"markedWords":[]},{"text":"文章夹叙夹议，以情动人。李密曾任蜀汉郎中和尚书郎，深知“批龙鳞，逆圣听”的后果，也知若只对皇帝讲理，有时也难以理喻，何况自己又是亡国之臣。故此，文章更多的不是议论，而是示“弱”，意在“陈情”，表述自己的苦衷。李密出生六个月后，父亲就去世；四岁时，母亲在舅父的逼迫下改嫁他人。祖母刘氏“躬亲抚养”尚未成人的李密，“臣无祖母，无以至今日；祖母无臣……相更为命”“臣密今年四十有四……愿乞终养”，言辞恳切，情义殷殷，足以打动任何人，更何况是曾经下诏“以孝治天下”来笼络人心的晋武帝。故此，文章达到了既以理服人，更以情动人的效果。","meaning":"围绕“文章夹叙夹议以情动人”展","central":"文章夹叙夹议，以情动人。","words":[],"markedWords":[]}]},{"id":"docx_23","theme":4,"title":"项脊轩志","author":"归有光〔明代〕","genre":"古文","idea":"文章借项脊轩的兴废，写与之有关的家庭琐事，表达人亡物在、三世变迁的感慨，也表达了作者对祖母、母 亲及妻子的思念之情。","central":"雨泽下注；","options":["文章借项脊轩的兴废，写与之有关的家庭琐事，表达人亡物在、三世变迁的感慨，也表达了作者对祖母、母 亲及妻子的思念之情。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"雨泽下注；每移案，顾视无可置者。又北向，不能得日，日过午已昏。余稍","meaning":"围绕“雨泽下注”展开","central":"雨泽下注；","words":[],"markedWords":["下","无可置者","得日","昏","余"]},{"text":"坐，万籁有声；而庭阶寂寂，小鸟时来啄食，人至不去。三五之夜，明月半","meaning":"围绕“坐万籁有声”展开","central":"坐，万籁有声；","words":[],"markedWords":[]},{"text":"墙，桂影斑驳，风移影动，珊珊可爱。","meaning":"围绕“墙桂影斑驳风移影动珊”展","central":"墙，桂影斑驳，风移影动，珊珊可爱。","words":[],"markedWords":["珊珊"]},{"text":"然余居于此，多可喜，亦多可悲。先是庭中通南北为一。","meaning":"围绕“然余居于此多可喜亦多”展","central":"然余居于此，多可喜，亦多可悲。","words":[],"markedWords":["先是","一"]},{"text":"于兹。”妪又曰：“汝姊在吾怀，呱呱而泣；娘以指叩门扉曰：‘儿寒乎？","meaning":"围绕“于兹”展开","central":"于兹。","words":[],"markedWords":["于"]},{"text":"中，一日，大母过余曰：“吾儿，久不见若影，何竟日默默在此，大类女郎","meaning":"围绕“中一日大母过余曰吾儿”展","central":"中，一日，大母过余曰：“吾儿，久不见若影，何竟日默默在此，大类女","words":[],"markedWords":["过余","竟","日","大类"]},{"text":"瞻顾遗迹，如在昨日，令人长号不自禁。","meaning":"围绕“瞻顾遗迹如在昨日令人”展","central":"瞻顾遗迹，如在昨日，令人长号不自禁。","words":[],"markedWords":["瞻顾遗迹"]},{"text":"轩凡四遭火，得不焚，殆有神护者。","meaning":"围绕“轩凡四遭火得不焚殆有”展","central":"轩凡四遭火，得不焚，殆有神护者。","words":[],"markedWords":["殆"]},{"text":"余既为此志，后五年，吾妻来归，时至轩中，从余问古事，或凭几学书。","meaning":"最后两段式补叙，表达对亡妻的怀","central":"余既为此志，后五年，吾妻来归，时至轩中，从余问古事，或凭几学书。","words":[],"markedWords":["余既为此志","来归","书"]},{"text":"吾妻归宁，述诸小妹语曰：“闻姊家有阁子，且何谓阁子也？”其后六年，","meaning":"围绕“吾妻归宁述诸小妹语曰”展","central":"吾妻归宁，述诸小妹语曰：“闻姊家有阁子，且何谓阁子也？","words":[],"markedWords":["归宁","述诸小妹语曰","且"]},{"text":"吾妻死，室坏不修。其后二年，余久卧病无聊，乃使人复葺南阁子，其制稍","meaning":"围绕“吾妻死室坏不修”展开","central":"吾妻死，室坏不修。","words":[],"markedWords":["制"]},{"text":"异于前。然自后余多在外，不常居。","meaning":"围绕“异于前”展开","central":"异于前。","words":[],"markedWords":[]}]},{"id":"docx_24","theme":4,"title":"兰亭集序","author":"王羲之〔魏晋〕","genre":"古文","idea":"文章先叙述了兰亭因 修禊事而“群贤毕至 ”，说 明作诗的缘由；又用“一觞 一咏，亦足以畅叙幽情 ”描 写了作诗时的情景，指明了 《兰亭集》是一部游宴诗集， 有众多的作者，诗是即席之 作；结尾以“故列序时人，录其所说 ”说明成书的经过， 又以“后之览者，亦将有感 于斯文 ”指出这部诗集的意 义。同时，本文作者善于借 题发挥，从一次普通的游宴 活动谈到他的生死观，并以 此批判了当时士大夫阶层中 崇尚虚无的思想倾向。变了，事情不同了， 的思想情趣是一样的。 文有所感慨。","central":"永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。","options":["文章先叙述了兰亭因 修禊事而“群贤毕至 ”，说 明作诗的缘由；又用“一觞 一咏，亦足以畅叙幽情 ”描 写了作诗时的情景，指明了 《兰亭集》是一部游宴诗集， 有众多的作者，诗是即席之 作；结尾以“故列序时人，录其所说 ”说明成书的经过， 又以“后之览者，亦将有感 于斯文 ”指出这部诗集的意 义。同时，本文作者善于借 题发挥，从一次普通的游宴 活动谈到他的生死观，并以 此批判了当时士大夫阶层中 崇尚虚无的思想倾向。变了，事情不同了， 的思想情趣是一样的。 文有所感慨。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群","meaning":"围绕“永和九年岁在癸丑暮春”展","central":"永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。","words":[],"markedWords":[]},{"text":"引以为流觞曲水，列坐其次。虽无丝竹管弦之盛，一觞一咏，亦足以畅叙幽","meaning":"围绕“引以为流觞曲水列坐其”展","central":"引以为流觞曲水，列坐其次。","words":[],"markedWords":["引","流觞曲水","次","幽"]},{"text":"是日也，天朗气清，惠风和畅。仰观宇宙之大，俯察品类之盛，所以游","meaning":"围绕“是日也天朗气清惠风和”展","central":"是日也，天朗气清，惠风和畅。","words":[],"markedWords":["是日","惠风","品类之盛","所以游"]},{"text":"目骋怀，足以极视听之娱，信可乐也。","meaning":"围绕“目骋怀足以极视听之娱”展","central":"目骋怀，足以极视听之娱，信可乐也。","words":[],"markedWords":["目骋怀","极","信"]},{"text":"夫人之相与，俯仰一世。或取诸怀抱，悟言一室之内；或因寄所托，放","meaning":"这一段是议论和抒情。作者在表达","central":"夫人之相与，俯仰一世。","words":[],"markedWords":["夫人之","一世","取诸","怀抱","一室之内","因","所托放"]},{"text":"有的人在室内晤谈，互相倾吐心里话；（诸，相当于“之于”。怀抱，心怀。）有的人在室内晤谈，互相倾吐心里话；（诸，相当于“之于”。怀抱，心怀。）（有的人）把情怀寄托在所爱好的事物上，（有的人）把情怀寄托在所爱好的事物上，人与人相互交往，很快便度过一生。ǔ","meaning":"围绕“有的人在室内晤谈互相”展","central":"有的人在室内晤谈，互相倾吐心里话；","words":[],"markedWords":["有的人在室内","互相倾吐心里话","诸相当于之于","怀抱心怀","有的人把情怀","在所爱好的事物上","人与人","便度过一生","qǔ"]},{"text":"不知老之将至；及其所之既倦，情随事迁，感慨系之矣。向之所欣，俯仰之","meaning":"围绕“不知老之将至”展开","central":"不知老之将至；","words":[],"markedWords":["不知老之将至","所","既倦","情随事迁感慨","之","向"]},{"text":"感情随着情况的变化而变化，感慨随着这种变化而有所不同，","meaning":"围绕“感情随着情况的变化而”展","central":"感情随着情况的变化而变化，感慨随着这种变化而有所不同，","words":[],"markedWords":["感情随着情况","的变化而变化感慨"]},{"text":"每览昔人兴感之由，若合一契，未尝不临文嗟悼，不能喻之于怀。固知","meaning":"围绕“每览昔人兴感之由若合”展","central":"每览昔人兴感之由，若合一契，未尝不临文嗟悼，不能喻之于怀。","words":[],"markedWords":["每览昔人兴感之","若合一契","嗟","不能","之于怀","知"]},{"text":"一死生为虚诞，齐彭殇为妄作。后之视今，亦犹今之视昔，悲夫！故列叙时","meaning":"感悟人生短暂，时光流逝；感慨死","central":"一死生为虚诞，齐彭殇为妄作。","words":[],"markedWords":["死生为","彭殇为","列叙时"]},{"text":"人，录其所述，虽世殊事异，所以兴怀，其致一也。后之览者，亦将有感于","meaning":"围绕“人录其所述虽世殊事异”展","central":"人，录其所述，虽世殊事异，所以兴怀，其致一也。","words":[],"markedWords":["人","致"]},{"text":"王羲之：303-361，一说321-379，字逸少，祖籍琅玡临沂（今属山东），后迁居会稽山阴（今浙江绍兴）。曾任右军将军、会稽内史，世称“王右军”，是东晋伟大的书法家，有“书圣”之誉。他的儿子王献之书法造诣也很高，与王羲之并称“二王”。王羲之的代表作品有楷书《乐毅论》《黄庭经》，草书《十七帖》，行书《姨母帖》《孔侍中帖》《丧乱帖》等。其中，《兰亭集序》为书家所敬仰，被称作“天下第一行书”。","meaning":"围绕“王羲之303-361”展","central":"王羲之：303-361，一说321-379，字逸少，祖籍琅玡临沂（今属山东），后迁居会稽山阴（今浙江绍兴）。","words":[],"markedWords":["王羲之"]}]},{"id":"docx_25","theme":4,"title":"归去来兮辞并序","author":"陶渊明〔魏晋〕","genre":"古文","idea":"“序 ”中交代了作者出仕和“ 自免去职 ”的原因，“辞 ”中则抒写了作者归田的决心、归田时的愉快心情和 归田后的乐趣。作者通过对田园生活的赞美和对劳动生活的歌颂，表明了他对当时的政治，以及仕宦生活的不满与 否定，反映了他蔑视功名利禄的高尚情操，也流露出了他委运乘化、乐天安命的思想。","central":"怅然慷慨，深愧平生之志。","options":["“序 ”中交代了作者出仕和“ 自免去职 ”的原因，“辞 ”中则抒写了作者归田的决心、归田时的愉快心情和 归田后的乐趣。作者通过对田园生活的赞美和对劳动生活的歌颂，表明了他对当时的政治，以及仕宦生活的不满与 否定，反映了他蔑视功名利禄的高尚情操，也流露出了他委运乘化、乐天安命的思想。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"怅然慷慨，深愧平生之志。犹望一稔，当敛裳宵逝。寻程氏妹丧于武昌，情","meaning":"围绕“怅然慷慨深愧平生之志”展","central":"怅然慷慨，深愧平生之志。","words":[],"markedWords":["慷慨","敛裳宵逝","寻","情"]},{"text":"飘飘而吹衣。问征夫以前路，恨晨光之熹微。","meaning":"围绕“飘飘而吹衣”展开","central":"飘飘而吹衣。","words":[],"markedWords":["问征夫以前路","晨光之"]},{"text":"幼入室，有酒盈樽。引壶觞以自酌，眄庭柯以怡颜。倚南窗以寄傲，审容膝","meaning":"围绕“幼入室有酒盈樽”展开","central":"幼入室，有酒盈樽。","words":[],"markedWords":["盈樽","引","庭","以","颜","寄","傲","容膝"]},{"text":"之易安。园日涉以成趣，门虽设而常关。策扶老以流憩，时矫首而遐观。云","meaning":"围绕“之易安”展开","central":"之易安。","words":[],"markedWords":["之易安","园","日","以成趣","以流憩","时","首而"]},{"text":"ìì时时抬头遥望远方（的天空）。","meaning":"围绕“ìì时时抬头遥望远方”展","central":"ìì时时抬头遥望远方（的天空）。","words":[],"markedWords":["yì","时时","头","的天空"]},{"text":"既窈窕以寻壑，亦崎岖而经丘。木欣欣以向荣，泉涓涓而始流。善万物之得","meaning":"围绕“既窈窕以寻壑亦崎岖而”展","central":"既窈窕以寻壑，亦崎岖而经丘。","words":[],"markedWords":["以","壑","崎岖而经丘","万物之"]},{"text":"已矣乎！寓形宇内复几时？曷不委心任去留？胡为乎遑遑欲何之？富贵","meaning":"围绕“已矣乎”展开","central":"已矣乎！","words":[],"markedWords":["已矣乎","复几时","不","心任","胡为乎","欲"]},{"text":"登上（水边）向阳的高地，放声长啸，","meaning":"围绕“登上水边向阳的高地放”展","central":"登上（水边）向阳的高地，放声长啸，","words":[],"markedWords":["登上","长啸"]},{"text":"流而赋诗。聊乘化以归尽，乐夫天命复奚疑！","meaning":"围绕“流而赋诗”展开","central":"流而赋诗。","words":[],"markedWords":["以","乐夫天命","奚疑"]},{"text":"姑且顺随自然的变化，走到生命的尽头。乐天安命，还有什么可疑虑的呢？","meaning":"围绕“姑且顺随自然的变化走”展","central":"姑且顺随自然的变化，走到生命的尽头。","words":[],"markedWords":["的变化","乐天安","命还","什么可疑虑的呢"]},{"text":"陶渊明：约365-427，一名潜，字元亮，号五柳先生，私谥靖节。东晋诗人、辞赋家。浔阳柴桑（今江西九江西南）人。曾任江州祭酒、镇军参军、彭泽令等，后辞官归隐。长于诗文辞赋，诗多描绘田园风光及其在农村生活的情景，其中往往隐寓着他对污浊官场的厌恶和不愿同流合污的精神，以及对太平社会的向往。田园生活是陶渊明诗文的主要题材，相关作品有《饮酒》《归园田居》《桃花源记》《五柳先生传》《归去来兮辞》《桃花源诗》等。","meaning":"围绕“陶渊明约365-42”展","central":"陶渊明：约365-427，一名潜，字元亮，号五柳先生，私谥靖节。","words":[],"markedWords":["陶渊明"]},{"text":"语言朴素，音调和谐。文章用词自然，直抒胸臆，不加雕饰，呈现出一种天然和谐的纯净之美。","meaning":"围绕“语言朴素音调和谐”展开","central":"语言朴素，音调和谐。","words":[],"markedWords":[]}]},{"id":"docx_26","theme":5,"title":"种树郭橐驼传","author":"柳宗元〔唐代〕","genre":"古文","idea":"通过给郭橐驼立传，巧妙地把“养树 ”与“养民 ”联系起来，委婉含蓄地说明了顺民之性以养民的道理，揭 露讽刺了统治者苛政繁令对百姓的骚扰侵害，提出宽简为政、让百姓安居乐业的主张。","central":"其乡曰丰乐乡，在长安西。","options":["通过给郭橐驼立传，巧妙地把“养树 ”与“养民 ”联系起来，委婉含蓄地说明了顺民之性以养民的道理，揭 露讽刺了统治者苛政繁令对百姓的骚扰侵害，提出宽简为政、让百姓安居乐业的主张。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"其乡曰丰乐乡，在长安西。驼业种树，凡长安豪富人为观游及卖果者，","meaning":"围绕“其乡曰丰乐乡在长安西”展","central":"其乡曰丰乐乡，在长安西。","words":[],"markedWords":["种树","观游","卖果"]},{"text":"皆争迎取养。视驼所种树，或移徙，无不活；且硕茂，早实以蕃。他植者虽","meaning":"围绕“皆争迎取养”展开","central":"皆争迎取养。","words":[],"markedWords":["移徙","硕茂","早","以"]},{"text":"凡植木之性，其本欲舒，其培欲平，其土欲故，其筑欲密。既然已，勿动勿","meaning":"围绕“凡植木之性其本欲舒其”展","central":"凡植木之性，其本欲舒，其培欲平，其土欲故，其筑欲密。","words":[],"markedWords":["植木之","本","培","其土欲故","筑","然","勿动勿"]},{"text":"虑，去不复顾。其莳也若子，其置也若弃，则其天者全而其性得矣。故吾不","meaning":"围绕“虑去不复顾”展开","central":"虑，去不复顾。","words":[],"markedWords":["虑","去不复顾","莳","若子","其","也若弃","全","不"]},{"text":"害其长而已，非有能硕茂之也；不抑耗其实而已，非有能早而蕃之也。他植","meaning":"围绕“害其长而已非有能硕茂”展","central":"害其长而已，非有能硕茂之也；","words":[],"markedWords":["害其长","抑耗","其实","早","蕃"]},{"text":"者则不然。根拳而土易，其培之也，若不过焉则不及。苟有能反是者，则又","meaning":"围绕“者则不然”展开","central":"者则不然。","words":[],"markedWords":["拳","土易","若不过焉则不及"]},{"text":"，（培土）如果不是多了，就是不够。","meaning":"围绕“培土如果不是多了就是”展","central":"，（培土）如果不是多了，就是不够。","words":[],"markedWords":["培土如果不是多了","就是不够"]},{"text":"爱之太恩，忧之太勤。旦视而暮抚，已去而复顾。甚者，爪其肤以验其生枯，","meaning":"围绕“爱之太恩忧之太勤”展开","central":"爱之太恩，忧之太勤。","words":[],"markedWords":["爱之太","旦","暮","其","以验其"]},{"text":"摇其本以观其疏密，而木之性日以离矣。虽曰爱之，其实害之；虽曰忧之，","meaning":"第二部分，写郭橐驼种树与他人种","central":"摇其本以观其疏密，而木之性日以离矣。","words":[],"markedWords":["疏密","离"]},{"text":"问者曰：“以子之道，移之官理，可乎？”驼曰：“我知种树而已，理，","meaning":"围绕“问者曰以子之道移之官”展","central":"问者曰：“以子之道，移之官理，可乎？","words":[],"markedWords":["官","理"]},{"text":"而呼曰：‘官命促尔耕，勖尔植，督尔获，","meaning":"围绕“而呼曰‘官命促尔耕勖”展","central":"而呼曰：‘官命促尔耕，勖尔植，督尔获，","words":[],"markedWords":["勖尔植"]},{"text":"遂而鸡豚。’鸣鼓而聚之，击木而召之。吾小人辍飧饔以劳吏者，且不得暇，","meaning":"围绕“遂而鸡豚”展开","central":"遂而鸡豚。","words":[],"markedWords":["而鸡豚","木","吾","小人","辍","以劳吏者"]}]},{"id":"docx_27","theme":5,"title":"石钟山记","author":"苏轼〔宋代〕","genre":"古文","idea":"通过记叙作者对石钟山得名由来的探究过程，说明要弄清楚事情的真相必须“ 目见耳闻 ”，不可“臆断其有 无 ”的道理。","central":"事不目见耳闻，而臆断其有无，可乎？","options":["通过记叙作者对石钟山得名由来的探究过程，说明要弄清楚事情的真相必须“ 目见耳闻 ”，不可“臆断其有 无 ”的道理。","作品只是在罗列景物，没有表达思想或情感。","作品认为个人努力毫无意义，只能服从命运。","作品的核心是追求财富与地位，不涉及其他价值。"],"paragraphs":[{"text":"事不目见耳闻，而臆断其有无，可乎？郦元之所见闻，殆与余同，而言","meaning":"第3段，写作者探明石钟山得名由","central":"事不目见耳闻，而臆断其有无，可乎？","words":[],"markedWords":["臆断","殆"]},{"text":"不能言。此世所以不传也。而陋者乃以斧斤考击而求之，","meaning":"围绕“不能言”展开","central":"不能言。","words":[],"markedWords":["言","此世所以不传也","陋者","以斧斤","而","之"]},{"text":"歌，项王乃大惊曰：“汉皆已得楚乎？是何楚人之多也！”项王则夜起，饮","meaning":"第一段写垓下被围的困境。重点写","central":"歌，项王乃大惊曰：“汉皆已得楚乎？","words":[],"markedWords":["歌","汉皆已得楚乎","何楚人之多也","则"]},{"text":"帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慷慨，自","meaning":"围绕“帐中”展开","central":"帐中。","words":[],"markedWords":["幸从","慷慨"]},{"text":"为诗曰：“力拔山兮气盖世！时不利兮骓不逝！骓不逝兮可奈何！虞兮虞兮","meaning":"围绕“为诗曰力拔山兮气盖世”展","central":"为诗曰：“力拔山兮气盖世！","words":[],"markedWords":["逝","可奈何"]},{"text":"平明，汉军乃觉之，令骑将灌婴以五千骑追之。项王渡淮，骑能属者百余人","meaning":"围绕“平明汉军乃觉之令骑将”展","central":"平明，汉军乃觉之，令骑将灌婴以五千骑追之。","words":[],"markedWords":["平明","乃","以","属"]},{"text":"耳。项王至阴陵，迷失道，问一田父，田父绐曰“左”。左，乃陷大泽中。","meaning":"围绕“耳”展开","central":"耳。","words":[],"markedWords":["田父","左"]},{"text":"以故汉追及之。项王乃复引兵而东，至东城，乃有二十八骑。汉骑追者数千","meaning":"围绕“以故汉追及之”展开","central":"以故汉追及之。","words":[],"markedWords":["以故","东"]},{"text":"人。项王自度不得脱。谓其骑曰：“吾起兵至今八岁矣，身七十余战，所当","meaning":"第二段写项羽从垓下突围成功到再","central":"人。","words":[],"markedWords":["度","身"]},{"text":"者破，所击者服，未尝败北，遂霸有天下。然今卒困于此，此天之亡我，非","meaning":"围绕“者破所击者服未尝败北”展","central":"者破，所击者服，未尝败北，遂霸有天下。","words":[],"markedWords":["败北","卒"]},{"text":"战之罪也。今日固决死，愿为诸君快战，必三胜之，为诸君溃围，斩将，刈","meaning":"围绕“战之罪也”展开","central":"战之罪也。","words":[],"markedWords":["固决死","快战","刈"]},{"text":"旗，令诸君知天亡我，非战之罪也。”","meaning":"围绕“旗令诸君知天亡我非战”展","central":"旗，令诸君知天亡我，非战之罪也。","words":[],"markedWords":["旗"]}]}];
